(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["oc"] = {"ui":{"skip":"Anar al contengut","back":"← Tornar a AI-gile","lang.button":"Lenga : {name}","lang.dialog":"Causís una lenga","lang.search":"Cercar de lengas","lang.none":"Cap de lenga correspond","lang.notYet":"{name} es pas encara traduch","theme.aria":"Cambiar de tèma : clar, escur o negre","theme.toLight":"Passar al tèma clar","theme.toDark":"Passar al tèma escur","theme.toBlack":"Passar al tèma negre (negre vertadièr, doç pels ecrans OLED)","words.underline":"Soslinhar aqueles mots sus la pagina","words.underlineHelp":"Passa lo cursor sus un mot puntejat o tòca-lo per veire çò que vòl dire.","words.col.todo":"Cartas causidas per ara : l'equipa i començarà après.","words.col.doing":"Una IA trabalha ara sus aquesta carta.","words.col.review":"Una IA a acabat lo trabalh ; una autra lo verifica abans qu'arribe a tu.","words.col.verify":"Te espèra : ensaja-o e digas se foncciona.","words.col.team":"Tas nòtas o tas responsas, que esperan que l'equipa las prenga.","words.col.done":"Acabat e acceptat.","index.title":"AI-gile : ton equipa de dev IA, sus un sol tablèu","index.description":"AI-gile es un tablèu kanban per las equipas de còdi amb IA. Trabalhan mentre dormisses ; tu recebes una pichona pila de causas a decidir, ensajar e acceptar.","hero.logoAlt":"Icòna del tablèu AI-gile","hero.h1.html":"Ton equipa de dev IA, sus un sol&nbsp;tablèu.","hero.alpha":"🐣 Pre-alfa barrada","hero.alphaTitle":"Precòç e pas acabat : mercé d'ensajar !","hero.lede":"Bastisson mentre dormisses. Te desrevelhas amb una pichona pila : unas question, unas causas a ensajar, un diamant violet o doas. Clica, accèpta, e tòrna a ton café.","dl.windows":"Aplicacion Windows","dl.browser":"Lançar dins lo navegador","dl.messenger":"📱 Messenger per ton telefòn","dl.soon":"Lèu disponible","dl.notify":"🔔 Avisatz-me quand dobrirà","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, mas l'equipa a pas jamai besonh d'un café en pè. (Fan de stand-ups tot parièr.)","pitch.h2":"AI-gile en tant de mots coma vòles","pitch.lede":"Causís una longor, d'un mot a 144. Cada longor es una descripcion pròpria, escricha per aquela talha. Tira lo cursor o utiliza las sagetas.","pitch.rangeLabel":"Longor en mots","pitch.dice":"🎲 una autra version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caractèr","pitch.chars.other":"{n} caractèrs","count.line.html.one":"{n} carta sul tablèu en aquesta ora","count.line.html.other":"{n} cartas sul tablèu en aquesta ora","people.humans.html.one":"👥 {n} uman","people.humans.html.other":"👥 {n} umans","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} al trabalh en aquesta ora","people.working.html.other":"⚡ {n} al trabalh en aquesta ora","pre.title":"AI-gile : quicòm se bastís","pre.description":"Aquí se bastís quicòm : un tablèu ont d'equipas IA bastisson çò que demandatz, e vos ensenhan en camin. Per ara, pre-alfa barrada entre amics.","pre.h1":"Aquí se bastís quicòm. 🤫","pre.line":"Un tablèu ont d'equipas IA bastisson çò que demandatz, e vos ensenhan en camin. Per ara, pre-alfa barrada entre amics.","pre.btn":"🔔 Avisatz-me quand dobrirà","pre.peek":"Darrièr lo veire : lo tablèu vertadièr, en dirècte. Cada carta es una barra colorada.","pre.peekFake":"Darrièr lo veire : çò que sembla un tablèu al trabalh.","pre.night":"🌙 Lo vilhaire de nuèch es al comand · 😴 l'uman se repausa","features.aria":"Çò que fa","f.pile.h":"Una pila sonque per tu","f.pile.html":"<b>Per tu</b> recampa tot çò que te espèra, dins totes los projèctes : question, causas a ensajar, tascas que sonque un uman pòt far. Ta fila ditz çò qu'es lo seguent e quant de temps pren.","f.sleep.h":"Equipas que trabalhan mentre dormisses","f.sleep.p":"Cada projècte a un cap e una equipa d'agents IA. Comenta una carta e l'equipa se desrevelha, fa lo trabalh e lo te torna amb d'etapas que un uman cansat pòt seguir.","f.tester.h":"Un tèster IA verifica primièr","f.tester.p":"Abans que res te tòque, un tèster seguís las etapas dins una còpia de l'aplicacion e mòstra çò qu'a vist, amb una captura d'ecran. Percor los reüssits e accèpta en un clic.","f.proof.h":"De pròvas, pas de prometenças","f.proof.p":"Cada liurason mòstra çò qu'a cambiat : los fichièrs, lo diff, las capturas d'ecran. Cap de besonh de dobrir cada aplicacion per saber s'es acabat.","f.chat.h":"Charra amb tos caps","f.chat.p":"Una barra a l'estil Discord : una icòna per projècte, de diamants violets per çò que te cal. Manda una idèa a un cap ; la càmbia en cartas e en plan, amb un boton ✅ Go.","f.tidy.h":"Se ten ordenat tot sol","f.tidy.p":"Las cartas parentas se fondon en una, los títols embolhats son corregits, e una verificacion dels tokens manten lo còdi leugièr. Mens de causas entre las qualas cambiar, mens de qué pensar.","f.private.h":"Teu, sus ton ordenador","f.private.li1":"Lo tablèu fonciona sus ta pròpria maquina e respond pas qu'a tu.","f.private.li2":"Los DMs privats entre personas son chifrats de cap a cap.","f.private.li3":"Cap de compte, cap de traçaire, cap de cookie.","f.lang.h":"Dins ta lenga","f.lang.p":"Mai de 120 lengas, del neerlandés, del galés e del japonés al pirata, a Yoda e al klingon, amb un cambiament rapid cap a l'anglés pel jargon del mestièr.","f.service.h":"D'una idèa a un servici vertadièr","f.service.p":"As bastit quicòm amb l'IA que las gents utilizan ara ? Marca-lo coma servici e lo tablèu t'ajuda a lo far foncionar plan : verificacions de disponibilitat, una pagina d'estat publica, d'incidents amb un rapòrt, de cambiaments que demandan un Anar, de salvagardas verificadas cada jorn. L'ajuda t'ensenha cada pas en camin.","msgr.h2":"AI-gile Messenger : ton equipa dins la pòcha","msgr.p1":"Parla a ton equipa IA sens dobrir lo tablèu. Charra amb tos caps de projècte e tos amics, consulta las estapas de tèst d'una carta e respond-i, tot dempuèi ton telefòn.","msgr.p2":"Per l'associar, escana un còdi QR sus ton tablèu. Primièr còp ? Una charrada de demo amistosa te fa far lo torn.","msgr.when":"Android d'en primièr, puèi una version web pels telefòns e l'iPhone.","msgr.who":"Ton cap de projècte","msgr.b1":"La correccion del mòde escur es prèsta. Vòls las estapas de tèst ?","msgr.b2":"Òc, se te plai !","msgr.b3":"1. Dobrís los Reglatges. 2. Causís Escur. Te sembla bon ?","tl.aria":"Cronologia, de la primièra convèrsa a la fuèlha de rota","tl.h2":"De la primièra charra a çò que ven","tl.lede":"Datas e oras vertadièras, dins ton fus orari. Aprèp uèi es lo plan, sens cap de data prometuda.","tl.today":"Uèi","tl.planned":"previst","tl.doing":"en cors","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Rejonh-nos","join.lede":"AI-gile es bastit per un original barbut amb AuDHD e qualques batalhas amb la santat mentala, e un fum d'agents pacients. Per ara es privat, en alfa barrada amb d'amics. Vòles ensajar quand dobrirà ?","join.btn":"Marcar mon interès","join.small":"T'escriurem per corrièl, pas mai","footer.tag":"AI-gile. Cap de traçaire, cap de cookie, cap de café en pè.","footer.licence":"Licéncia professionala","footer.status":"Estat","footer.privacy":"Çò que gardam","footer.thanks":"Sonadas mercés a ChilledChat","form.sending":"Mandadís…","form.failed":"Aquò a pas foncionat : tòrna ensajar mai tard.","form.offline":"Pas pogut joindre AI-gile : tòrna ensajar mai tard.","form.keep":"O utilizam sonque per te respondre, puèi o escafam. Cap de traçaire, cap de cookie.","form.keepLink":"Çò que gardam","interest.title":"AI-gile : avisa-me quand l'alfa dobrirà","interest.description":"Daissa ton corrièl per saber quora l'alfa o la beta barrada d'AI-gile dobrirà.","interest.h1":"🔔 Avisa-me quand dobrirà","interest.lede":"AI-gile es en pre-alfa barrada. Daissa ton corrièl e t'escriurem un còp, quand i aurà una plaça per tu.","interest.email":"Ton corrièl","interest.which":"Quin ensag ?","interest.alpha":"Alfa barrada : precòça, brusca, amb fòrça cambiaments","interest.beta":"Beta : mai establa, mai tard","interest.both":"L'un o l'autre, çò que vendrà primièr","interest.submit":"Met-me sus la lista","interest.thanks":"Mercé ! Ès sus la lista.","licence.title":"AI-gile : licéncia professionala","licence.description":"Utilizas AI-gile dins ton ofici ? Demanda una licéncia professionala gratuita.","licence.h1":"📜 Licéncia professionala","licence.lede":"Utilizas AI-gile al trabalh ? Digas-nos qual siás e çò que fas. Se fa un pauc de ben, la licéncia es gratuita.","licence.company":"Entrepresa","licence.website":"Site web","licence.what":"Çò que fas","licence.how":"Cossí aquò ajuda lo monde","licence.email":"Corrièl","licence.submit":"Demandar","licence.thanks":"Mercé ! Te respondrem per corrièl.","status.title":"Estat d'AI-gile","status.h1":"Estat d'AI-gile","status.quiet":"Tot es tranquil","status.intro":"AI-gile fonciona ara? Aquesta pagina verifica lo site, lo partatge de tablèus, las sonadas e lo telecargament cada 5 minutas.","status.up":"Fonciona (a respondut en {ms} ms)","status.slow":"A pas respondut a la darrièra verificacion, ensagi tornamai","status.down":"En pana: a pas respondut a las doas darrièras verificacions","status.svc.web":"Site web","status.svc.web.offers":"Aqueste site: çò qu'es AI-gile, e lo formulari d'interès","status.svc.boards":"Partatge de tablèus","status.svc.boards.offers":"Tablèus publics, messatges entre amics e convits","status.svc.calls":"Sonadas","status.svc.calls.offers":"Votz, vidèo e partatge d'ecran dins AI-gile","status.svc.download":"Telecargament","status.svc.download.offers":"L'installador Windows e los ligams de convit","status.checking":"Verificacion…","status.offline":"Pòdi pas joindre lo servici d'estat ara (tornarai ensajar)","status.updated":"mes a jorn {ago}","status.justNow":"ara meteis","status.min":"i a {n} min","status.hours":"i a {n} h","status.days":"i a {n} j","privacy.title":"AI-gile: çò que gardam","privacy.h1":"Çò que gardam","privacy.lede":"En cort: sonque çò que nos mandas, e pas per long temps.","privacy.only":"Sonque çò que nos mandas: çò que picas dins un formulari, coma ton corrièl. Pas res mai sus tu.","privacy.sealed":"Es sagelat per que nòstre servidor lo pòsca pas legir: dins ton navegador, abans que parte (sus un navegador mai vièlh, tre qu'arriba). Sonque nòstre pròpri tablèu lo pòt dobrir.","privacy.server":"Es escafat del servidor tre qu'arriba a nòstre tablèu. Tot çò que i demòra après 30 jorns es escafat de tot biais.","privacy.board":"Lo gardam sus nòstre tablèu sonque fins que t'ajam respondut, puèi l'escafam d'aquí tanben.","privacy.none":"Cap de traçaire, cap de cookie, cap d'estatistica.","privacy.local":"Ta lenga e ta causida entre tèma clar o escur demòran dins ton pròpri navegador. Nos son pas jamai mandadas.","privacy.ask":"Lo vòls veire desaparéisser mai lèu? Respond a nòstre corrièl e fai-nos-o saber.","live.h2":"Agacha-lo se bastir, en dirècte","live.caption":"Cada carta es amagada : vezes la forma del trabalh, pas las paraulas.","live.watching.one":"en dirècte : {n} agacha","live.watching.other":"en dirècte : {n} agachan","live.last.now":"Darrièra carta desplaçada pas qu'ara","live.last.min.one":"Darrièra carta desplaçada fa {n} min","live.last.min.other":"Darrièra carta desplaçada fa {n} min","live.last.hour.one":"Darrièra carta desplaçada fa {n} ora","live.last.hour.other":"Darrièra carta desplaçada fa {n} oras","live.last.day.one":"Darrièra carta desplaçada fa {n} jorn","live.last.day.other":"Darrièra carta desplaçada fa {n} jorns","live.offline":"Lo tablèu en dirècte pren un pauc d'alen. Torna d'aquí un moment.","live.cols":"Backlog|A far|En cors|Verificacion de l'equipa|Per tu de testar|Per l'equipa|Fach","footer.models":"AI-gile fa foncionar de modèls IA per tu. Çò que dison e fan es lor, doncas verifica abans de lor far fisança.","privacy.ai.h":"La part IA","privacy.ai.models":"AI-gile es lo tablèu. Lo trabalh es fach per de modèls IA d'autras entrepresas, coma Claude, Codex e Gemini, sus tos pròpris comptes.","privacy.ai.check":"Çò que escrivon e fan ven d'eles e pòt èsser fals. Verifica abans de t'i fisar o de o publicar.","privacy.ai.files":"Càmbian de fichièrs e executan de comandas dins los dossièrs que connectas. Fai una còpia de salvament.","privacy.ai.send":"Çò que balhas a un modèl vai a l'entrepresa que lo fa foncionar, jos sas condicions. Las condicions e los còstes de cada entrepresa s'aplican.","privacy.ai.asis":"AI-gile es una version d'assag precòça, balhada coma es."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robòts.","Delegat."]},{"n":2,"texts":["Kanban robotic.","Agents, ordenats.","Idèas, bastidas."]},{"n":3,"texts":["Kanban per robòts.","Las idèas venon foncions.","Kanban d'agents gratuit."]},{"n":5,"texts":["Tablèu kanban menat per d'agents.","Escrives de cartas. Los agents bastisson.","Gratuit, local, ensajat, un pauc fòl."]},{"n":8,"texts":["Un kanban gratuit ont trabalhan d'agents IA.","Escriu una idèa. Los agents la bastisson. Accèptas.","Agile per un uman e fòrça robòts paciënts."]},{"n":13,"texts":["Un tablèu kanban sus ton ordenador ont d'agents IA prenon las cartas.","Escriu una idèa. Una equipa d'agents la bastís. Un tèster la verifica.","Gratuit, cap de compte, cap de traçaire : un tablèu, de robòts e tu al comande."]},{"n":21,"texts":["AI-gile es un tablèu kanban per trabalhar amb d'agents de còdi IA. Prenon las cartas ; tu las ensajas e las accèptas.","Cada projècte a un cap e una equipa d'agents IA. Comenta quina carta que siá e l'equipa se met a trabalhar.","Un tablèu personal e gratuit que fonciona sus ton ordenador. Los trabalhaires son de robòts. Cel que ditz òc, es tu."]},{"n":34,"texts":["Possas d'idèas sus un tablèu. Una equipa d'agents IA las càmbia en foncions que fonciònan, las ensaja e te las torna amb d'etapas per ensajar. Res compta coma acabat tant que ne diguèsses pas òc.","AI-gile es un tablèu kanban fach a l'ostal que Rich a bastit amb fòrça ajuda dels agents que ara maneja. Es gratuit, fonciona sus ton ordenador, e es partejat amb d'amics, pas vendut.","Imagina un tablèu kanban ordinari, amb de colomnas del Backlog a Fach, levat que las cartas las prenon d'agents IA. Raportan lor avançament, pausan de question quand blocan, e esperan totjorn ton aprovacion."]},{"n":55,"texts":["AI-gile es un tablèu kanban ont l'equipa es facha d'agents IA. Cada projècte a un cap que planifica lo trabalh e d'ajudaires que lo bastisson. Quand una foncion es prèsta, un tèster IA l'ensaja e pren una captura d'ecran, puèi arriba dins ta pila. Accèpta-la, o comenta e la tornan trabalhar.","Tot a començat coma la manièra d'una persona de seguir fòrça sessions de còdi IA a l'encòp, puèi es venguda un vertadièr tablèu. Fonciona sus ta maquina, demanda pas de compte e a pas cap de traçaire. Es gratuit per los amics e los curioses. Es tanben pas acabat, doncas espèra-te a d'arèstas e a una susprèsa de còps que i a.","Siaguem sinceres. Te cal totjorn aver las idèas, e te cal totjorn verificar los resultats. Çò que fa AI-gile, es tot çò d'entremièg : ten las cartas en òrdre, desrevelha l'agent bon quand comentas, mòstra exactament çò qu'a cambiat, e met tot aquò dins una pichona pila per tu."]},{"n":89,"texts":["AI-gile es un tablèu kanban gratuit que fas foncionar sus ton pròpri ordenador. Al lòc de personas, cada projècte a una equipa d'agents IA : un cap que càmbia tas idèas en cartas e en plan, e d'ajudaires que prenon las cartas per òrdre de prioritat. Quand quicòm es bastit, un tèster IA seguís las etapas de tèst e te mòstra çò qu'a vist. Puèi aquò espèra dins una sola pila marcada Per tu. L'accèptas, o comentas e l'equipa ensaja un còp mai. Res arriba jamai a Fach sens tu.","Qualques foncions que t'espèras benlèu pas. Un gach de la nuèch manten la colomna A far garnida mentre dormisses, en causissent de cartas que demandan cap de responsa de ta part. Un comptaire de tokens mòstra quant los agents an utilizat uèi e aquesta setmana, e lo Mòde Sens Tokens lor ditz d'arrestar de despendre. Pòdes escriure a d'amics, e los messatges privats son chifrats de cap a cap. Lo tablèu parla a l'entorn de 120 lengas, e mai lo neerlandés, lo flamenc, lo pirata e lo klingon. Res d'aquò còsta un ciment, e degun ensaja pas de t'o vendre.","AI-gile es un pichon projècte personal, pas una entrepresa. Rich voliá s'ocupar de mantun projècte de còdi IA sens dobrir cada aplicacion per anar veire, doncas el e los agents an bastit un tablèu per aquò, puèi an emplegat lo tablèu per bastir lo rèsta de se meteis. Es en pre-alfa barrada, çò que vòl dire que fonciona, mai que mai, per un punhat d'amics. I a pas de pagina de tarifas, pas de letra d'informacion e pas de plan de creissença. Se te sembla util, pòdes demandar d'ensajar quand dobrirà un pauc mai."]},{"n":144,"texts":["AI-gile es un tablèu kanban per un uman e fòrça agents IA. Fonciona sus ton pròpri ordenador e es completament gratuit. Apondes de projèctes, e cada projècte recep un cap e una pichona equipa. Charras amb lo cap, un pauc coma sus Discord, e descrives una idèa ; lo cap la càmbia en cartas e en plan, puèi espèra qu'aprimes Go. L'equipa trabalha las cartas per òrdre de prioritat, amb una linha de comanda simpla facha per los modèls de lenga. Abans que res te torne, un tèster IA seguís las etapas dins una còpia de l'aplicacion e ligà una captura d'ecran. Lo trabalh acabat arriba dins ta pila amb los fichièrs cambiats e lo diff. L'accèptas, o daisses un comentari e l'equipa se desrevelha e ensaja tornar. Sonque tu pòdes mudar una carta cap a Fach.","Una jornada amb AI-gile, a pauc près. Al ser daisses qualques comentaris : aqueste boton es al mal endreit, aquela lista deuriá èsser triada, poiriam aver un mòde escur. Vas te jaire. Los agents legisson los comentaris, fan los cambiaments, los ensajan e te los tornan. Se A far se voida, lo gach de la nuèch lo torna emplir amb de cartas del backlog que demandan cap de responsa de ta part. Al matin i a una pichona pila : unas question e unas causas d'ensajar, caduna amb d'etapas qu'una persona ensomiada pòt seguir e una captura d'ecran de la causa que fonciona. Percorres tot, accèptas çò qu'es bon e tornas lo rèsta. Un comptaire de tokens mòstra çò qu'aquò tot a consumit, e lo Mòde Sens Tokens es aquí per las setmanas magras. Puèi dejunas, e per aquò los agents pòdon pas encara ajudar.","Primièr, çò qu'AI-gile es pas. Es pas una startup, es pas en venda e degun recampa pas tas donadas. Es un tablèu gratuit que fonciona sus ton ordenador, sens compte, sens traçaire e sens cookie. Çò qu'es : un sol lòc ordenat per veire a l'encòp totes tos projèctes de còdi IA, amb una equipa d'agents que fa las cartas e tu que prenes las decisions. Fonda las cartas parentas, corregís los títols embolhats, e gaita que lo còdi demòre leugièr. Parla a l'entorn de 120 lengas, del neerlandés e del flamenc al pirata e al klingon. Los amics se pòdon escriure, en privat e chifrat. Es estat bastit per Rich e un fum d'agents paciënts, en s'utilizant quasi totjorn el meteis. Es en pre-alfa barrada, doncas es brut en qualques endreits. Se te sembla amusant, demanda gentilament e benlèu entraràs mai lèu."]}],"quips":{"1":"Un mot. Agardit. Benlèu tròp agardit.","3":"Tres mots. Ja mai sincèr que la màger part de las paginas de produch.","8":"Uèch mots. Encara mai cort qu'un stand-up.","21":"Las longors son de story points, çaquelà. Òc ben, evidentament.","55":"Cinquanta-cinc mots. Doas cartas se son acabadas mentre legissiás aquò.","144":"Aquò es la longa. I a pas de 233. Los agents son anats se jaire."}},"timeline":{"first-idea.name":"La primièra idèa","first-idea.line":"La tota primièra convèrsa, abans que i aguèsse un sol bocin de còdi.","first-board.name":"Primièr tablèu","first-board.line":"Un tablèu que seguís sa pròpria bastison : cartas, colomnas, tirar e daissar, projèctes.","team-roles.name":"Equipa e ròtles","team-roles.line":"Perfils d'agents, modèls d'equipa, espacis e qual fa qué.","install.name":"Installacion e versions","install.line":"Un zip qu'un amic pòt installar, mesas a jorn automaticas, canals e tornada en arrièr.","usage-saver.name":"Estalvi d'utilizacion","usage-saver.line":"Mesurar çò que còstan las execucions, tenir lo còdi leugièr, estalviar ton limit.","friends.name":"Amics e partiment","friends.line":"DMs privats, un relai embolhat, convits, ròtles e projèctes partejats.","languages.name":"Lengas","languages.line":"Cada tèxte d'ecran dins un fichièr de lenga, amb lo neerlandés e lo flamenc d'en primièr.","ai-tester.name":"Tèster IA","ai-tester.line":"Un tèster verifica cada liurason primièr e mòstra çò qu'a vist.","website.name":"Lo site web","website.line":"aigile.lol, la pagina de presentacion e aquesta cronologia.","streaming.name":"Charra e difusion","streaming.line":"Discord, Twitch, OBS, mòde streamer, GIFs e emojis.","no-ai.name":"Edicion sens IA","no-ai.line":"Un tablèu per las gents que programan sens IA, e de tablèus publics.","night-watch.name":"Gach de la nuèch","night-watch.line":"Un gach e Scrum Master mantenon las equipas en tasca mentre dormisses.","p-more.name":"Tot lo rèsta","p-more.line":"D'idèas mai pichonas que son encara a esperar son torn.","p-android.name":"Telefòn e Android","p-android.line":"Accedir a ton tablèu dempuèi un telefòn, puèi una aplicacion Android nativa.","p-release.name":"Alfa e al-delà","p-release.line":"Alfa barrada, lo site en linha, puèi la beta.","p-languages.name":"Mai de lengas","p-languages.line":"130 lengas, e un mòde d'immersion pels aprenents.","p-engines.name":"Mai de motors IA","p-engines.line":"Causís Claude, Codex, Gemini, Copilot o Cursor per cada agent.","p-pro.name":"Practica professionala","p-pro.line":"Etiquetas de risc, barrièras de fusion, cartas d'incident e garda-fòlzes.","p-self.name":"Se ocupar de tu","p-self.line":"Mòde cansat, rampèls de suenh de se e 4:20.","p-servers.name":"Servidors e escala","p-servers.line":"Paramètres globals de servidor, ròtles e planificacion de la creissença.","p-livestream.name":"Extras de difusion","p-livestream.line":"Charra Twitch, emojis personalizats e una vista publica en dirècte."},"words":{"button":"📖 Jargon del mestièr","h":"📖 Mots explicats","intro":"Formacion gratuita en lenga simpla : cada mot que rescontras d'una primièra idèa fins a un servici sus lo qual se fisa lo monde, amb l'Agile, la construccion, la seguretat e lo trabalh amb l'IA pel camin.","search":"Cercar un mot…","none":"Cap de mot correspond.","close":"Barrar","count":{"one":"{count} mot","other":"{count} mots"},"groups":[{"id":"idea","name":"💡 Idèa e descobèrta"},{"id":"plan","name":"🗺️ Planificar lo trabalh"},{"id":"agile","name":"🔁 Manièras de trabalhar agilas"},{"id":"build","name":"🛠️ Bastir"},{"id":"test","name":"🧪 Tèsts e qualitat"},{"id":"change","name":"🔀 Cambiar sens dangièr"},{"id":"run","name":"🛎️ Far foncionar un servici"},{"id":"sec","name":"🔒 Seguretat e vida privada"},{"id":"ai","name":"🤖 Trabalhar amb l'IA"},{"id":"money","name":"💰 Argent e licéncias"}],"list":[{"id":"discovery","g":"idea","word":"Descobèrta","text":"L'estapa del començament ont se cerca quin problèma val la pena d'èsser resolgut e per qual, abans que res siá bastit.","also":["fasa de descobèrta","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Enonciat del problèma","text":"Una o doas frasas que dison qual a un problèma, de qué se tracta e perqué es important, per que tot lo monde vise la meteissa tòca.","also":["enonciats del problèma","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Utilizaire","text":"Una persona que se sèrv d'aquò que bastisses. Sos besonhs son la rason del trabalh.","also":["utilizaires","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Partida interessada","text":"Tota persona que se preocupa de çò que sortirà del trabalh o que n'es tocada, coma las personas que lo pagan, que s'en servisson o que ne fan l'assisténcia.","also":["partidas interessadas","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Una persona imaginària mas realista que representa un genre d'utilizaire, per que l'equipa se pòsca demandar « Sam o trobariá aisit ? »","also":["personas"]},{"id":"userresearch","g":"idea","word":"Recèrca amb los utilizaires","text":"Parlar amb de personas vertadièras e las agachar per saber çò qu'an besonh, puslèu que de devinar.","also":["entrevistas d'utilizaires","user research","user interviews"]},{"id":"journey","g":"idea","word":"Percors de l'utilizaire","text":"Las etapas que fa una persona per menar quicòm a tèrme, del primièr còp que n'ausís parlar fins a la fin, tanben defòra de ton produch. Lo dessenhar mòstra ont se blòcan.","also":["percors d'utilizaires","percors del client","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Ponch dolorós","text":"Quicòm que agaça o alentís lo monde uèi. Los bons produches levan los ponches dolorosos.","also":["ponches dolorosos","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Ipotèsi de partença","text":"Quicòm que creses mas as pas encara verificat. Escriure las ipotèsis de partença mòstra çò que cal ensajar en primièr.","also":["ipotèsis de partença","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipotèsi","text":"Una supausicion que pensas verificar, amb çò qu'espèras que se passe, coma « lo monde s'inscriurà se lo primièr mes es gratuit ».","also":["ipotèsis","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Experiéncia","text":"Un pichon assag planificat per saber se una idèa foncionarà, abans de i apostar fòrça.","also":["experiéncias","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Pròva de concèpte (PoC)","text":"Un assag rapid e grossièr per veire se una idèa pòt foncionar. Sovent se gieta un còp qu'as la responsa.","also":["PoC","proof of concept","pròva de concèpte"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Un modèl precòce del produch, sovent d'imatges ont se pòt clicar, per ensajar l'idèa amb de monde abans de la bastir per de bon.","also":["prototips","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Esquèma de pagina (wireframe)","text":"Un crocis simple d'un ecran que mòstra ont van las causas, sens color ni contengut vertadièr.","also":["wireframe","wireframes","esquèmas de pagina"]},{"id":"mockup","g":"idea","word":"Maqueta (mockup)","text":"Un imatge detalhat de l'aparéncia qu'aurà un ecran, amb de colors e un tèxte vertadièrs, mas res fonciona pas encara.","also":["mockup","mockups","mock-up","mock-ups","maquetas"]},{"id":"bizcase","g":"idea","word":"Dossièr de justificacion (business case)","text":"Las rasons de menar un projècte : çò que còsta, çò que rapòrta o estalvia, e los risques.","also":["business case","business cases","dossièr de justificacion"]},{"id":"feasibility","g":"idea","word":"Faisabilitat","text":"Se quicòm se pòt vertadièrament bastir e mantenir amb lo temps, l'argent e las competéncias qu'as.","also":["faisable","feasibility"]},{"id":"outcome","g":"idea","word":"Resultat esperat (outcome)","text":"Lo cambiament que vòls pel monde, coma mens de rendètz-vos mancats. Compta mai que la quantitat de causas bastidas.","also":["outcome","outcomes","resultats esperats"],"noTip":1},{"id":"output","g":"idea","word":"Produccion (output)","text":"Quicòm que l'equipa produsís, coma un ecran novèl o un rapòrt. Lo far vòl pas dire automaticament qu'ajudarà qualqu'un.","also":["output","outputs","produccions"],"noTip":1},{"id":"successmetric","g":"idea","word":"Indicador de capitada","text":"Un nombre que te ditz se lo trabalh a fach çò per que serviá, coma mai de monde que van fins a la fin de lor comanda.","also":["indicadors de capitada","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Indicador clau de performància (KPI)","text":"Un nombre important qu'agaches per veire se tot va ben, coma las inscripcions per setmana.","also":["KPI","KPIs","key performance indicator","indicador clau"]},{"id":"okr","g":"idea","word":"Objectius e resultats claus (OKR)","text":"Una manièra de fixar d'objectius : l'objectiu ditz çò que vòls, e qualques resultats claus son los nombres que mostran que l'as atench.","also":["OKR","OKRs","objectius e resultats claus"]},{"id":"product","g":"plan","word":"Produch","text":"Çò qu'es bastit e mantengut pels utilizaires, coma una aplicacion, un site web o un esplech.","also":["produches","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vision del produch","text":"Una declaracion corta que ditz qual ajuda lo produch e ont va a long tèrme.","also":["declaracion de vision","vision statement","vision"]},{"id":"po","g":"plan","word":"Responsable del produch (PO)","text":"La persona que decidís çò que se bastís e dins quin òrdre, per que l'equipa trabalhe totjorn sus çò que compta mai. Dins AI-gile, es tu.","also":["PO","product owner","product owners","responsables del produch"]},{"id":"pm","g":"plan","word":"Gerent de produch (PM)","text":"La persona que s'ocupa de la direccion d'un produch : quins problèmas resòlv, per qual e perqué. PM pòt tanben voler dire gerent de projècte, doncas verifica de quin se tracta.","also":["PM","product manager","product managers","gerents de produch"]},{"id":"projmgr","g":"plan","word":"Gerent de projècte","text":"La persona que fa tenir un projècte dins los delais e lo budget, en seguissent qual fa de qué e per quora.","also":["gerents de projècte","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Fuèlha de rota (roadmap)","text":"Un plan grossièr de çò que ven dins los mes que vènon, dins l'òrdre. Mòstra la direccion, pas de datas exactas, e càmbia a mesura que aprenes.","also":["roadmap","roadmaps","fuèlhas de rota"]},{"id":"milestone","g":"plan","word":"Jalon","text":"Un punt d'un projècte que val la pena de marcar, coma « primièra version en linha » o « 100 utilizaires ».","also":["jalons","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Produch minimum viable (MVP)","text":"La version mai pichona d'un produch que servís pasmens a de monde vertadièr, per aprene d'eles d'ora.","also":["MVP","MVPs","minimum viable product","produch minimum viable"]},{"id":"requirement","g":"plan","word":"Exigéncia","text":"Quicòm que lo produch acabat deu far o èsser.","also":["exigéncias","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Perimètre","text":"Çò qu'es compres dins lo trabalh e, tant important, çò que l'es pas.","also":["dins lo perimètre","fora del perimètre","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Derivacion del perimètre (scope creep)","text":"Quand s'apondon de mai en mai de causas al trabalh, un pauc a cada còp, sens que degun s'accòrde sul temps o lo còst de mai, e lo trabalh s'acaba pas jamai del tot.","also":["scope creep","feature creep","derivacion del perimètre"]},{"id":"feature","g":"plan","word":"Foncionalitat","text":"Una causa que lo produch sap far pel monde, coma « reïnicializar ton senhal ».","also":["foncionalitats","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Un gròs tròç de trabalh, tròp grand per un còp, doncas es copat en cartas mai pichonas.","also":["epics","epic","epicas"]},{"id":"story","g":"plan","word":"Istòria d'utilizaire","text":"Un pichon tròç de trabalh escrich del costat de l'utilizaire : « Coma client, vòli gardar mon panièr, per l'acabar mai tard. » Dobrís una conversa sus çò que cal bastir.","also":["istòrias d'utilizaire","user story","user stories"]},{"id":"ac","g":"plan","word":"Critèris d'acceptacion (AC)","text":"Las verificacions que una carta deu passar per comptar coma acabada, convengudas abans de començar, coma « lo panièr es totjorn aquí aprèp una desconnexion e una reconnexion ».","also":["AC","acceptance criteria","critèris d'acceptacion"]},{"id":"task","g":"plan","word":"Tasca","text":"Un sol trabalh a far, sovent un pichon pas d'una istòria mai granda.","also":["tascas","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Bilhet (ticket)","text":"Un autre mot per una carta : un tròç de trabalh o una demanda, que se seguís del començament fins a la fin.","also":["ticket","tickets","bilhets"]},{"id":"priority","g":"plan","word":"Prioritat","text":"Lo nivèl d'importància o d'urgéncia d'una causa al respècte de tot lo demai, per que lo trabalh mai important passe en primièr.","also":["prioritats","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritizacion","text":"Metre lo trabalh dins l'òrdre d'importància. Una manièra correnta es MoSCoW : Must (cal), Should (caldriá), Could (poiriá), Won't (pas aqueste còp).","also":["prioritizar","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimacion","text":"Una idèa aproximativa de la talha o de la durada d'un tròç de trabalh. Es una supausicion, pas una promessa.","also":["estimacions","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Punts d'istòria (story points)","text":"Una manièra d'estimar la talha del trabalh en comparant las cartas entre elas (« environ dos còps tant granda coma aquela ») puslèu qu'en oras. Servisson pas a comparar d'equipas.","also":["story point","story points","punt d'istòria"]},{"id":"tshirt","g":"plan","word":"Talhas de T-shirt","text":"Estimar la talha del trabalh en S, M, L o XL. Rapid e prou bon per la planificacion del començament.","also":["t-shirt sizes","T-shirt sizing","talhas de t-shirt"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Un jòc per estimar : tot lo monde mòstra una carta de talha al meteis moment, puèi los que mostran la mai granda e la mai pichona explican perqué.","also":["Scrum poker","poker de planificacion"]},{"id":"dependency","g":"plan","word":"Dependéncia","text":"Quand un tròç de trabalh pòt pas començar o s'acabar tant qu'un autre es pas fach.","also":["dependéncias","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blocatge","text":"Tot çò que empacha lo trabalh d'avançar ara, coma una responsa que manca o un esplech copat.","also":["blocatges","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Data limit","text":"La data abans la quala quicòm deu èsser acabat.","also":["datas limits","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Liurable","text":"Quicòm de concrèt que lo trabalh produsís e liura, coma una pagina que fonciona o un rapòrt.","also":["liurables","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prevision","text":"Una prediccion de çò que se passarà probablament, coma quora lo trabalh serà acabat, segon çò que sabes fins ara.","also":["previsions","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Mesura (metric)","text":"Tot çò que mesures e seguisses dins lo temps, coma las visitas d'una pagina o lo temps que pren una correccion.","also":["mesuras","metric","metrics"]},{"id":"feedback","g":"plan","word":"Retorn (feedback)","text":"Çò que lo monde te ditz de ton trabalh, de bon e de marrit. Lo recebre d'ora e sovent es lo còr de l'Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"La lista d'espèra de las idèas e del trabalh pas encara planificat, amb lo mai important en naut. Res d'aquí es pas trabalhat tant que passa pas dins A far."},{"id":"sprint","g":"agile","word":"Sprint","text":"Un moment de trabalh cort e fixe (sovent una o doas setmanas, jamai mai d'un mes) amb un objectiu e un ensemble convengut de cartas a acabar.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un punt rapid de cada jorn : çò qu'a fach cada membre de l'equipa, çò que farà aprèp, e çò que l'empacha. En Scrum, s'apèla lo Scrum quotidian.","also":["standup","stand-ups","stand-up","daily scrum","daily stand-up","pichona reünion quotidiana"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una manièra de trabalhar ont las cartas avançan de colomna en colomna sul tablèu (coma A far, En cors, Fach) e l'equipa limita quant n'i a en cors a l'encòp, per que lo trabalh còrra."},{"id":"wip","g":"agile","word":"Limita WIP","text":"WIP es l'abreujament de « work in progress » (trabalh en cors). Una limita de WIP es lo nombre maximal de cartas qu'una colomna deu tenir a l'encòp, per que l'equipa acabe las causas abans d'en començar mai.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicion de Fach","text":"La corta lista de contraròtle de l'equipa sus çò que vòl dire « acabat », coma testat e explicat, abans que una carta te siá donada. Sa bessona, la Definicion de Prèst, ditz quand una carta es pro clara per començar.","also":["Definition of Ready","DoD","DoR","definicion de fach","definicion de prèst"]},{"id":"retro","g":"agile","word":"Retro","text":"Un agach regular enrèire sus la manièra de trabalhar de l'equipa, per se metre d'acòrdi sus una o doas causas a melhorar lo còp que ven. Abreujament de retrospectiva. Dins AI-gile una retro prepausa un cambiament de las manièras de trabalhar de l'equipa, e dises Go o Pas encara.","also":["retros","retrospectiva","retrospectivas"]},{"id":"swarm","g":"agile","word":"Eissam","text":"Tot lo monde sus lo pont : fòrça gents daissan lor autre trabalh per reparar amassa una causa urgenta fins que siá reglada. Dins AI-gile cada equipa ajuda sus un sol projècte, e los autres projèctes esperan entretant.","also":["eixam","swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"En Scrum, la persona qu'ajuda l'equipa a plan trabalhar : lèva çò que la bloca, ten las reünions sul bon camin e encoratja de bonas costumas, sens comandar degun. Dins AI-gile, lo Lead Scrum Master repèra las cartas blocadas, relança las equipas e te rapèla çò qu'espèra, sus cada projècte.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Una manièra de trabalhar per pichons passes : bastir un pauc, mostrar sovent de resultats vertadièrs, aprene de çò que ditz lo monde e cambiar lo plan en camin, puslèu que tot planificar a l'avança.","also":["Agile","desvolopament agile","manièras de trabalhar agilas"]},{"id":"manifesto","g":"agile","word":"Manifèst Agile","text":"Una declaracion corta escricha en 2001 per de creators de logicials. Met las personas, los resultats que foncionan, la collaboracion estrecha amb los clients e l'adaptacion al cambiament al-dessús dels plans pesucs e de la paperassa.","also":["Manifèst pel desvolopament agile de logicials","Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Cascada (Waterfall)","text":"La vièlha manièra de trabalhar : tot planificar, puèi tot bastir, puèi tot testar, una etapa aprèp l'autra. Los cambiaments tardièrs son dificils e cars.","also":["Waterfall","modèl en cascada","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteracion","text":"Un torn per bastir quicòm, lo verificar e lo melhorar. Lo trabalh agile es una cadena d'aqueles, e un sprint n'es una sòrta.","also":["iteracions","iteration","iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"Un tròç novèl que fonciona apondut al produch dins un sprint o un torn de trabalh, e que s'ajusta amb çò qu'èra ja aquí.","also":["increments","increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Una manièra agila de trabalhar coneguda : una pichona equipa trabalha per sprints corts cap a un objectiu, amb de ròtles definits e qualques reünions regularas per planificar, verificar e melhorar."},{"id":"scrumteam","g":"agile","word":"Equipa Scrum","text":"Lo pichon grop que fa lo trabalh en Scrum : un responsable del produch, un Scrum Master e los desvolopaires.","also":["equipas Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Eveniments Scrum","text":"Las reünions regularas en Scrum : la planificacion del sprint, lo Scrum quotidian, la revista del sprint e la retro. Fòrça monde las apelan cerimònias.","also":["cerimònias","cerimònias Scrum","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Planificacion del sprint","text":"La reünion del començament d'un sprint ont l'equipa se met d'acòrdi sus la rason d'èsser del sprint, quinas cartas prendre e cossí començar.","also":["reünion de planificacion","planning meeting","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Objectiu del sprint","text":"Una frasa que ditz per qué servís un sprint. De pichonas tascas pòdon cambiar en camin, pro que l'objectiu siá atench.","also":["objectius del sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog del sprint","text":"Las cartas causidas pel sprint en cors, amb lo plan de l'equipa per las menar a tèrme.","also":["backlogs del sprint","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog del produch","text":"La lista completa e ordenada de tot çò que poiriá èsser bastit pel produch, lo mai important en naut. Càmbia sens parar a mesura que aprenes.","also":["backlogs del produch","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Objectiu del produch","text":"Lo resultat mai grand cap al qual va lo produch, e que ajuda l'equipa a causir çò que fa aprèp.","also":["objectius del produch","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Afinament del backlog","text":"Repassar regularament lo backlog per rangar, copar, ordenar e detalhar las cartas, per que sián prèstas a èsser presas. Se ditz tanben backlog grooming.","also":["backlog grooming","refinement","afinament"]},{"id":"sprintreview","g":"agile","word":"Revista del sprint","text":"Una reünion a la fin d'un sprint ont l'equipa mòstra çò qu'a acabat e ausís çò que lo monde en pensa, per decidir çò que ven aprèp.","also":["revistas del sprint","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Mostrar lo trabalh acabat en trin de foncionar, en dirècte, a las personas que l'avián demandat.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Boita de temps (timebox)","text":"Una quantitat de temps fixa per quicòm. Quand s'acaba, t'arrèstas, quitament se tot es pas acabat.","also":["timebox","timeboxed","timeboxes","boita de temps"]},{"id":"velocity","g":"agile","word":"Velocitat","text":"Quant de trabalh una equipa acaba d'òrdinari dins un sprint, servís a planificar quant ne prendre lo còp que ven. Es pas una nòta de l'esfòrç que fa lo monde.","also":["velocitat de l'equipa","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Capacitat","text":"Quant de trabalh l'equipa pòt prendre sus una periòde, aprèp las vacanças e las autras tascas.","noTip":1},{"id":"burndown","g":"agile","word":"Grafic de burndown","text":"Un grafic del trabalh que demòra dins un sprint e que davala jorn aprèp jorn. Se la linha demòra plata, quicòm es blocat.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Grafic de burnup","text":"Un grafic del trabalh acabat que puja amb lo temps, a costat del total planificat, per veire quora i arribaràs.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Tablèu Kanban","text":"Lo tablèu pròpriament dich : una colomna per cada etapa del trabalh, amb las cartas que passan d'una colomna a l'autra.","also":["tablèus Kanban","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Flux tirat (pull)","text":"Una manièra de trabalhar ont un trabalh novèl comença pas que quand qualqu'un a plaça per lo prendre, puslèu que de lo butar sus un platèl ja plen.","also":["pull system","pull-based","sistèma tirat"]},{"id":"flow","g":"agile","word":"Flux","text":"Amb quina fluïditat lo trabalh traversa lo tablèu. Un bon flux vòl dire que las cartas avançan puslèu que de s'amassar.","also":["flux de trabalh","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Delai de liurason (lead time)","text":"Lo temps que passa entre lo moment que qualqu'un demanda quicòm e lo moment qu'es acabat.","also":["lead time","lead times","delai de liurason"]},{"id":"cycletime","g":"agile","word":"Temps de cicle","text":"Lo temps que pren una carta entre lo moment que lo trabalh comença vertadièrament e lo moment qu'es acabat.","also":["cycle time","cycle times","temps de cicles"]},{"id":"throughput","g":"agile","word":"Debit (throughput)","text":"Quantas cartas son acabadas en una setmana, o dins un temps qual que siá.","also":["throughput","throughput rate","debit"]},{"id":"bottleneck","g":"agile","word":"Estrangladura (bottleneck)","text":"L'unica etapa ont lo trabalh s'amassa e alentís tot çò que ven darrièr, coma lo col estrech d'una botelha.","also":["bottleneck","bottlenecks","estrangladura"]},{"id":"swimlane","g":"agile","word":"Carrièra (swimlane)","text":"Una linha en travèrs del tablèu que gropa de cartas d'un meteis genre, coma lo trabalh urgent o las cartas d'una equipa.","also":["swimlane","swimlanes","swim lane","carrièra"]},{"id":"lean","g":"agile","word":"Lean","text":"Una manièra de trabalhar que lèva lo gaspilhatge (tot çò que ajuda pas lo client) e fa que lo trabalh s'escorre plan."},{"id":"waste","g":"agile","word":"Gaspilhatge (waste)","text":"En Lean, tot çò que demanda d'esfòrç mas ajuda pas lo client, coma l'espèra, tornar far lo trabalh o bastir de causas que degun utiliza pas.","noTip":1},{"id":"kaizen","g":"agile","word":"Melhorament continú","text":"Melhorar un pauc tot lo temps amb de pichons cambiaments regulars, puèi verificar que an ajudat. Las retros son una manièra de o far. Se ditz tanben kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Equipa autoorganizada","text":"Una equipa que decidís ela-meteissa cossí far lo trabalh, puslèu que de recebre d'ordres pas a pas.","also":["autoorganizacion","equipa autogerida","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Equipa pluridisciplinària","text":"Una equipa que dispausa de totas las competéncias per menar lo trabalh a tèrme sola, coma lo dessenh, la construccion e los tèsts.","also":["cross-functional","cross-functional team","pluridisciplinària"]},{"id":"spike","g":"agile","word":"Spike","text":"Un cort moment de recèrca limitat dins lo temps per respondre a una question abans de s'engatjar dins lo vertadièr trabalh.","also":["spikes","recèrca limitada"]},{"id":"rework","g":"agile","word":"Retrabalh","text":"Tornar far un trabalh perque lo primièr còp èra pas bon.","also":["rework","reworked","retrabalhar"]},{"id":"safe","g":"agile","word":"Agile a granda escala (SAFe)","text":"Manièras d'utilizar l'Agile a travèrs fòrça equipas dins una granda organizacion. SAFe (lo Scaled Agile Framework) n'es un exemple conegut.","also":["scaled Agile","Agile a granda escala"]},{"id":"repo","g":"build","word":"Repo","text":"Lo dossièr del projècte amb son còdi e tot son istoric de commits. Pòt èsser sus ton ordenador, sus GitHub, o los dos.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linha de trabalh a part dins lo còde, per poder cambiar de causas sens tocar la version principala.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantanèu enregistrat del còde, amb una pichona nòta de çò que a cambiat. Pòdes totjorn tornar a un.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Mandar tas fòtos gardadas (commits) d'aqueste ordenador a la còpia partejada en linha, coma GitHub, per que sián salvadas e que d'autres las pòscan recuperar."},{"id":"merge","g":"build","word":"Merge","text":"Amassar los cambiaments d'una branca dins una autra, sovent tornant dins la version principala."},{"id":"pr","g":"build","word":"Pull request","text":"Demandar que los cambiaments d'una branca sián verificats e amassats dins la version principala. D'unes sites l'apèlan merge request.","also":["PR","PRs","merge request","demanda de fusion"]},{"id":"refactor","g":"build","word":"Refactor","text":"Rengar lo còde sens cambiar çò que fa : fichièrs mai pichons, noms mai clars, mens de repeticions."},{"id":"bug","g":"build","word":"Bug","text":"Quicòm que marcha pas coma deuriá.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revision per parièr","text":"Un parelh d'uèlhs de mai : qualqu'un autre que l'autor verifica lo trabalh abans que t'arribe, per que passe mens d'errors. Dins AI-gile, una autra IA verifica cada carta.","also":["revision de còdi","peer review","code review"]},{"id":"code","g":"build","word":"Còdi","text":"Las instruccions escrichas que dison a un ordenador çò que deu far. Se ditz tanben còdi font.","also":["còdi font","code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Lenga de programacion","text":"Una lenga per escriure de còdi, coma JavaScript, Python o Java. Caduna val mai per de trabalhs diferents.","also":["lengas de programacion","programming language","programming languages"]},{"id":"developer","g":"build","word":"Desvolopaire (dev)","text":"Qualqu'un que escriu e càmbia de còdi. Se ditz tanben programaire o engenhaire logicial.","also":["desvolopaires","programaire","programaires","engenhaire logicial","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Logicial","text":"Los programas que foncionan sus los ordenadors e los telefònes, al contrari de las maquinas elas-meteissas (lo material).","noTip":1},{"id":"app","g":"build","word":"Aplicacion (app)","text":"Abreujament d'aplicacion : un programa que lo monde utiliza per far quicòm, sus un telefòn, un ordenador o dins un navegador web.","also":["apps","app","aplicacions","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Aplicacion web","text":"Una aplicacion que fonciona dins un navegador web, doncas i a pas res a installar.","also":["aplicacions web","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (davant)","text":"La part d'una aplicacion que veses e sus la quala clicas : los ecrans, los botons e los mots, sovent dins ton navegador.","also":["front-end","frontend","davant"]},{"id":"backend","g":"build","word":"Back end (darrièr)","text":"La part d'una aplicacion que se passa darrièr l'escena, que garda las donadas e fa lo trabalh quand clicas quicòm, coma verificar ton senhal.","also":["back-end","backend","darrièr"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Trabalhar a l'encòp sul front end e sul back end.","also":["full-stack","pila completa"]},{"id":"ui","g":"build","word":"Interfàcia utilizaire (UI)","text":"Çò qu'una persona vei e utiliza sus l'ecran : la disposicion, los botons, los menuts e lo tèxte.","also":["UI","user interface","interfàcia","interfàcia utilizaire"]},{"id":"ux","g":"build","word":"Experiéncia utilizaire (UX)","text":"Çò qu'òm sent en utilizar quicòm : aisit, clar e agradiu, o embolhat e lent.","also":["UX","user experience","experiéncia utilizaire"]},{"id":"accessibility","g":"build","word":"Accessibilitat (a11y)","text":"Far que las causas sián utilizablas per tot lo monde, e tanben per las personas que veson pas plan, pòdon pas utilizar una mirga o se servisson d'un legeire d'ecran.","also":["a11y","accessibilitat"]},{"id":"responsive","g":"build","word":"Design adaptatiu (responsive)","text":"Concebre de paginas que s'adaptan e foncionan plan sus tota talha d'ecran, d'un telefòn a un gròs monitor.","also":["adaptatiu"]},{"id":"designsys","g":"build","word":"Sistèma de design","text":"Un kit partejat de colors, poliças, botons e règlas, per que cada ecran semble e se compòrte de la meteissa manièra.","also":["sistèmas de design","design system","design systems"]},{"id":"architecture","g":"build","word":"Arquitectura","text":"La forma generala d'un sistèma : quinas son las principalas pèças e cossí se parlan entre elas."},{"id":"database","g":"build","word":"Basa de donadas (BD)","text":"Un lòc ben ordenat per gardar d'informacions, coma un tablèu de calcul fòrça poderós que l'aplicacion pòt legir e modificar.","also":["bases de donadas","BD","DB","database","databases"]},{"id":"schema","g":"build","word":"Esquèma de basa de donadas","text":"La disposicion d'una basa de donadas : quinas taulas d'informacion conten e çò que va dins caduna.","also":["esquèma","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Abreujament de « structured query language » : la lenga emplegada per demandar d'informacions a fòrça basas de donadas o las modificar.","also":["Structured Query Language","lenga de requèstas estructurada"]},{"id":"data","g":"build","word":"Donadas","text":"Las informacions gardadas per un ordenador, coma de noms, de comandas o de paramètres.","also":["data","dataset","datasets","jòc de donadas"],"noTip":1},{"id":"server","g":"build","word":"Servidor","text":"Un ordenador totjorn alucat que respond a las requèstas d'autres ordenadors, coma mandar una pagina web quand la visitas.","also":["servidors","server","servers"]},{"id":"client","g":"build","word":"Client","text":"Lo costat que demanda quicòm, d'òrdinari ton navegador o ta aplicacion, que parla a un servidor. En comèrci, vòl tanben simplament dire un crompaire.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Abreujament d'« application programming interface » : un menut fixe de requèstas qu'un programa pòt far a un autre, coma demandar a un servici de metèo la prevision del jorn.","also":["APIs","application programming interface","interfàcia de programacion"]},{"id":"endpoint","g":"build","word":"Punt d'accès (endpoint)","text":"Un element del menut d'una API : una adreça web qu'un programa pòt apelar per recuperar o mandar quicòm.","also":["endpoint","endpoints","punts d'accès"]},{"id":"integration","g":"build","word":"Integracion","text":"Connectar dos sistèmas per que trabalhen amassa, coma ta botiga que manda las comandas a ton logicial de comptabilitat.","also":["integracions","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Un messatge qu'un sistèma manda a un autre tot sol al moment que quicòm se passa, coma « paiament recebut ».","also":["webhooks"]},{"id":"library","g":"build","word":"Bibliotèca","text":"Un còdi tot fach qu'una autra persona a escrich e que pòdes tornar emplegar al lòc de l'escriure tu-meteis.","also":["bibliotècas","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (estructura de basa)","text":"Una estructura tota facha per bastir una aplicacion que decidís una bona part de l'organizacion del còdi, coma l'ossada d'un ostal qu'emplisses.","also":["frameworks","estructura de basa"]},{"id":"sdk","g":"build","word":"Kit de desvolopament logicial (SDK)","text":"Una caissa d'esplechs, de còdi e d'exemples per bastir de logicials per una plataforma o un servici.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dependéncia logiciala","text":"Una bibliotèca o un esplech necessari a ton còdi per foncionar. Las tenir a jorn es important per la seguretat.","also":["dependéncias logicialas","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Paquet","text":"Un fais de còdi tot fach que pòdes installar e utilizar dins un projècte.","also":["paquets","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestionari de paquets","text":"Un esplech que va cercar e met a jorn los paquets dels quals ton còdi depend. npm es un exemple corrent.","also":["gestionaris de paquets","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"L'esplech lo mai espandit per gardar l'istoric dels cambiaments de còdi, jos forma de commits e de brancas."},{"id":"github","g":"build","word":"GitHub","text":"Un site web que garda los depaus Git en linha, per que las equipas pòscan partejar de còdi, revisar los cambiaments e seguir lo trabalh."},{"id":"vcs","g":"build","word":"Gestion de versions","text":"Gardar un istoric complet de cada cambiament dels fichièrs, per veire qual a cambiat de qué e tornar en arrèr se cal. Git o fa.","also":["version control","source control","version control system","contraròtle de version"]},{"id":"clone","g":"build","word":"Clonar","text":"Far ta pròpria còpia completa d'un depaus, amb son istoric, sus ton ordenador.","also":["clone","cloned","cloning","clonatge"]},{"id":"pull","g":"build","word":"Pull (recuperar)","text":"Recuperar los darrièrs commits de la còpia partejada (coma GitHub) sus ton ordenador. L'opausat de push.","also":["git pull","pull","recuperar"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branca principala","text":"La version oficiala del còdi de la quala tot lo monde part, sovent apelada main o master.","also":["main branch","master branch","branca main","branca master"]},{"id":"conflict","g":"build","word":"Conflicte de fusion","text":"Quand dos cambiaments tòcan las meteissas linhas de dos biaisses diferents, doncas l'ordenador los pòt pas jónher e qualqu'un deu causir.","also":["conflictes de fusion","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (diferéncias)","text":"Una vista que mòstra exactament çò qu'a cambiat entre dos versions : las linhas apondudas e las linhas levadas.","also":["diffs","diferéncias"]},{"id":"fork","g":"build","word":"Fork (bifurcacion)","text":"Ta pròpria còpia del depaus de qualqu'un mai, que pòdes modificar sens tocar lo sieu.","also":["forks","forked","bifurcacion"]},{"id":"script","g":"build","word":"Script","text":"Un pichon programa que fa un trabalh tot sol, coma rangar de fichièrs o aviar l'aplicacion.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (compilacion)","text":"Transformar lo còdi en quicòm prèst a foncionar, o lo resultat meteis, prèst a foncionar.","also":["builds","compilacion"],"noTip":1},{"id":"compile","g":"build","word":"Compilar","text":"Traduire lo còdi escrich per de personas dins una forma que l'ordenador pòt executar dirèctament.","also":["compile","compiler","compilador"]},{"id":"cli","g":"build","word":"Linha de comanda (CLI)","text":"Una fenèstra de tèxte ont tapes d'instruccions per l'ordenador al lòc de clicar. Se ditz tanben lo terminal.","also":["command line","command-line","CLI","terminal","linha de comanda"]},{"id":"config","g":"build","word":"Configuracion (config)","text":"Los paramètres que contrarotlan lo compòrtament d'un logicial, gardats a despart del còdi per que sián aisits de cambiar.","also":["config","configuration","configuracion"],"noTip":1},{"id":"envvar","g":"build","word":"Variabla d'environament","text":"Un paramètre balhat a un programa quand se lança, sovent emplegat per d'adreças o de senhals per que sián pas escriches dins lo còdi.","also":["variablas d'environament","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Desbugatge (debugging)","text":"Cercar perqué quicòm marcha pas, e lo reparar.","also":["debug","debugged","debugging","desbugar"]},{"id":"pairing","g":"build","word":"Programacion en par","text":"Doas personas (o una persona e una IA) que trabalhan amassa sul meteis còdi, una que tapa e l'autra que verifica.","also":["pair programming","pairing","programacion en binòmi"]},{"id":"docs","g":"build","word":"Documentacion (docs)","text":"Explicacions escrichas de cossí quicòm fonciona o cossí l'utilizar.","also":["documentacion","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Lo primièr fichièr a legir dins un depaus : de qué es lo projècte e cossí lo far foncionar.","also":["READMEs","legissètz-me"]},{"id":"legacy","g":"build","word":"Sistèma eretat (legacy)","text":"Un sistèma mai ancian totjorn utilizat que se cambia mal, sovent perque pas gaire de monde lo compren encara.","also":["sistèmas eretats","legacy system","legacy systems","legacy code","còdi eretat"]},{"id":"techdebt","g":"build","word":"Deute tecnic","text":"De rotas cortas que fan ganhar de temps ara mas alentisson los cambiaments d'aprèp, coma un prèst que fa venir d'interès. Refactorar lo rembolsa.","also":["deute tecnic","tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Una verificacion que quicòm fonciona coma deu. D'unes tèsts los fa l'ordenador tot sol a cada cambiament del còdi ; d'autres son tu qu'ensagis una carta acabada abans de l'acceptar.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Abreujament de « quality assurance » (assegurança de la qualitat) : tot çò que se fa per assegurar que lo trabalh es bon abans de passar en linha. Dins AI-gile, vòl dire las verificacions automaticas : quand QA es roge, quicòm a fracassat, e pòt pas passar en linha tant que es pas reparat.","also":["verificacions de qualitat","contraròtle de qualitat"]},{"id":"testpile","g":"test","word":"Pila de tèst","text":"Las cartas acabadas que t'esperan per las ensajar, una aprèp l'autra. N'accèptas una o la tornas mandar amb una nòta, e la seguenta arriba.","also":["pilas de tèst"]},{"id":"autotest","g":"test","word":"Tèst automatic","text":"Una verificacion que l'ordenador fa tot sol a cada còp que lo còdi càmbia, per trapar las errors d'ora.","also":["tèsts automatics","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Tèst manual","text":"Una persona que ensagia lo trabalh a la man per veire se se compòrta coma cal.","also":["tèsts manuals","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Tèst unitari","text":"Una pichona verificacion automatica d'un pichon tròç de còdi tot sol.","also":["tèsts unitaris","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Tèst d'integracion","text":"Una verificacion que mantuna part fonciona plan amassa, pas sonque una a una.","also":["tèsts d'integracion","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Tèst de cap a cap (E2E)","text":"Un tèst que fa coma un utilizaire vertadièr del començament a la fin, coma s'inscriure, crompar e pagar.","also":["E2E","end-to-end tests","tèst de cap a cap"]},{"id":"uat","g":"test","word":"Tèst d'acceptacion pels utilizaires (UAT)","text":"Las personas que an demandat lo trabalh l'ensagisson elas-meteissas e dison se fa çò que lor cal. La pila de tèsts d'AI-gile n'es una version.","also":["UAT","acceptance testing","tèst d'acceptacion"]},{"id":"regression","g":"test","word":"Regression","text":"Quicòm que foncionava e que s'es copat aprèp un cambiament. Los tèsts de regression verifican que las causas ancianas foncionan totjorn.","also":["regressions","regression test","regression tests","regression testing","tèst de regression"]},{"id":"smoke","g":"test","word":"Tèst de fum (smoke test)","text":"Una verificacion fòrça rapida que las causas principalas foncionan almens, per exemple tre qu'un cambiament passa en linha. Se fracassa, arrèsta-te e agacha.","also":["smoke test","smoke tests","tèsts de fum"]},{"id":"exploratory","g":"test","word":"Tèst exploratòri","text":"Ensajar lo produch en tota libertat e lo provar de totas las manièras, per trapar de problèmas que las verificacions planificadas mancarián.","also":["tèsts exploratòris","exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Cas de tèst","text":"Un scenari escrich a ensajar : las etapas, e çò que deuriá arribar.","also":["cases de tèst","test case","test cases"]},{"id":"coverage","g":"test","word":"Cobertura dels tèsts","text":"Quina part del còdi es verificada per de tèsts automatics. Mai n'i a, mai segur es sovent, mas una cobertura nauta soleta pròva pas que tot fonciona plan.","also":["cobertura","code coverage","cobertura del còdi"]},{"id":"testdata","g":"test","word":"Donadas de tèst","text":"D'informacions d'exemple inventadas emplegadas pendent los tèsts, per que cap de detalh privat d'una persona vertadièra siá pas expausat.","also":["jòc de tèst","test fixtures"]},{"id":"edgecase","g":"test","word":"Cas limit","text":"Una situacion estranha als limits, coma un formulari void o un nom amb un apostròf, ont las causas se copan sovent.","also":["cases limits","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Camin urós","text":"Lo camin normal ont tot va ben. Un bon tèst ensagia tanben los camins mens uroses."},{"id":"perftest","g":"test","word":"Tèst de performància","text":"Verificar la rapiditat de quicòm e cossí resistís a la pression.","also":["tèsts de performància","performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Tèst de cargament","text":"Verificar cossí un sistèma se'n sortís quand fòrça monde l'utiliza a l'encòp.","also":["tèsts de cargament","load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Tèst de seguretat","text":"Cercar las febletats que poirián daissar qualqu'un abusar d'un sistèma o veire çò que deuriá pas.","also":["tèsts de seguretat","security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Tèst d'accessibilitat","text":"Verificar que de personas amb de capacitats diferentas pòdon utilizar lo produch, tanben amb un legeire d'ecran o sonque amb un clavièr.","also":["tèsts d'accessibilitat","accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting (revision automatica del còdi)","text":"Una verificacion automatica que repèra las errors probablas e l'estil desordenat dins lo còdi, coma un corrector ortografic pels programas.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Analisi estatica","text":"Verificar lo còdi per trapar de problèmas en lo legissent automaticament, sens lo far foncionar.","also":["analisi estatica del còdi","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Tèst instable (flaky)","text":"Un tèst que a còps capita e a còps fracassa sens rason clara, doncas òm s'i pòt pas fisar completament.","also":["tèsts instables","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Reproduire (repro)","text":"Tornar far arribar un bug exprès en seguissent las meteissas etapas, per que pòsca èsser estudiat e reparat. Escriure aquelas etapas es la part mai utila d'un rapòrt de bug.","also":["repro","reproduce","reproduire","steps to reproduce","etapas per reproduire"]},{"id":"severity","g":"test","word":"Gravetat","text":"A quin ponch l'efècte d'un problèma es marrit, d'un pichon agaçament fins al moment que tot s'arrèsta.","also":["nivèl de gravetat","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copiar una version novèla del logicial sus los ordenadors que lo fan foncionar, coma una còpia de tèst o lo servici en linha."},{"id":"release","g":"change","word":"Publicacion","text":"Un paquet nomenat de trabalh acabat que passa en linha tot ensems, amb de nòtas cortas sus çò qu'a cambiat. 🚀 Publicacions escriu las nòtas a partir de las cartas fachas.","also":["publicacions","release","releases"]},{"id":"rollback","g":"change","word":"Tornar enrèire","text":"Tornar a la darrièra version que foncionava quand una novèla fa problèma. Dins AI-gile, Tornar enrèire amassa en una sola lista las etapas d'anullacion escrichas sus cada cambiament.","also":["retorn enrèire","tornat enrèire","rollback"]},{"id":"live","g":"change","word":"En linha","text":"La version vertadièra que las gents utilizan, al contrari d'una còpia per ensajar. Los desvolopaires ne dison tanben la produccion.","also":["en dirècte","produccion","production"],"noTip":1},{"id":"change","g":"change","word":"Cambiament","text":"Un cambiament previst sus quicòm de que las gents dependon, escrich abans : qué, perqué, lo risc, quora, e cossí l'anullar. Comença-ne un amb 🔀 Demandar un cambiament.","also":["cambiaments","demanda de cambiament","demandas de cambiament"],"noTip":1},{"id":"risk","g":"change","word":"Risc","text":"Quicòm que poiriá mal virar, notat segon qu'es probable e qu'es grèu. ⚠️ Riscs los garda dins una sola lista, la nòta mai nauta en primièr, cadun amb una data per i tornar agachar.","also":["riscs","registre dels riscs"]},{"id":"chgwin","g":"change","word":"Fenèstra de cambiament","text":"Los moments ont los cambiaments pòdon passar en linha, coma un dimars de ser tranquil. Fòra d'una fenèstra, una carta de cambiament pòt pas èsser acabada, levat s'es una urgéncia.","also":["fenèstras de cambiament","fenèstra"]},{"id":"gonogo","g":"change","word":"Anar / pas anar","text":"Una darrièra verificacion just abans qu'un cambiament passe en linha : cada persona que deu aprovar ditz Go o No go. Se fa pas que quand tot lo monde ditz Go.","also":["go/no go","go-no-go","anar/pas anar"]},{"id":"approval","g":"change","word":"Aprobacion","text":"Esperar un òc abans que lo trabalh comence. Una carta qu'un amic demanda, o un cambiament, espèra dins ✅ Aprobacions fins que l'aprobes o que lo refuses.","also":["aprobacions"]},{"id":"quiettime","g":"change","word":"Moment de calma","text":"Un moment, coma pendent un dirècte, una demo o la nuèch, ont res passa en linha. Las equipas contunhan de trabalhar e de testar, mas la mesa en linha espèra la fin. Alhors s'apèla un change freeze.","also":["moments de calma","gèl dels cambiaments","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Una manièra de trabalhar ont los que bastisson lo logicial e los que lo fan foncionar fan una sola equipa, amb fòrça automatizacion, per que los cambiaments passen en linha sovent e en seguretat."},{"id":"cicd","g":"change","word":"CI/CD (integracion e liurason contunha)","text":"Los cambiaments de cadun son amassats dins la version principala sovent e verificats automaticament a cada còp (integracion contunha), per que lo logicial siá totjorn prèst a passar en linha en quichant un boton (liurason contunha).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integracion contunha","liurason contunha"]},{"id":"contdeploy","g":"change","word":"Desplegament continú","text":"Un pas mai luènh que la liurason contunha : cada cambiament que passa las verificacions passa en linha tot sol, sens cap de boton a quichar.","also":["desplegaments continús","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Cadena d'automatizacion (pipeline)","text":"La seria automatica d'etapas que traversa un cambiament sus son camin cap a la linha, coma bastir, testar, puèi desplegar.","also":["pipeline","pipelines","cadenas d'automatizacion"]},{"id":"environment","g":"change","word":"Environament","text":"Una còpia separada del sistèma per un usatge, coma una per bastir, una per testar e la de produccion.","also":["environaments","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Environament de desvolopament","text":"La còpia ont trabalha un desvolopaire, sovent sus son pròpri ordenador, ont copar quicòm fa pas mal a degun.","also":["environament de dev","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Environament de tèst","text":"Una còpia separada del sistèma emplegada sonque per testar, per que lo servici vertadièr siá pas tocat.","also":["environaments de tèst","test environment","test environments"]},{"id":"staging","g":"change","word":"Preproduccion (staging)","text":"Una darrièra còpia installada tal coma la de produccion, per una verificacion finala abans qu'un cambiament passe en linha.","also":["staging","environament de preproduccion","staging environment"]},{"id":"artifact","g":"change","word":"Artefact de build","text":"Lo fichièr o lo fais qu'un build produsís, prèst a èsser gardat, verificat o mes en linha.","also":["artefactes de build","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Correccion d'urgéncia (hotfix)","text":"Una correccion urgenta mesa en linha rapidament, defòra del plan normal, perque quicòm d'important es copat.","also":["hotfix","hotfixes","correccions d'urgéncia"]},{"id":"patch","g":"change","word":"Patch (correctiu)","text":"Una pichona mesa a jorn que repara un bug o tampa un trauc de seguretat. Aplicar rapidament los correctius de seguretat es important.","also":["patch","patches","correctiu","security patch","security patches","correctiu de seguretat"]},{"id":"version","g":"change","word":"Numerò de version","text":"Una etiqueta coma 2.4.1 que ditz quina publicacion as. Sovent lo primièr nombre càmbia pels grands cambiaments e lo darrièr per las pichonas correccions.","also":["numeròs de version","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Nòtas de publicacion","text":"Una lista corta e clara de çò qu'a cambiat dins una publicacion, per los qu'o utilizan, amb las correccions e las limitas conegudas. Se ditz tanben changelog.","also":["jornal dels cambiaments","release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Interruptor de foncionalitat (feature flag)","text":"Un interruptor per alucar e atudar una foncionalitat, per que lo trabalh novèl pòsca passar en linha amagat e èsser alucat (o tornar atudat) sens publicacion novèla.","also":["feature flag","feature flags","feature toggle","feature toggles","interruptors de foncionalitat"]},{"id":"rollfwd","g":"change","word":"Tornar en avant (roll forward)","text":"Reparar una marrida publicacion en publicant rapidament una version novèla e corregida al lòc de tornar a l'anciana.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Publicacion canari (canary)","text":"Metre un cambiament en linha per un pichon grop d'en primièr, e per tot lo monde sonque quand sembla plan. Son nom ven dels canaris que los minaires menavan jos tèrra per los avisar d'ora del perilh.","also":["canary release","canary releases","canary","publicacions canari"]},{"id":"bluegreen","g":"change","word":"Desplegament blau-verd","text":"Gardar doas còpias del sistèma en linha e far passar lo monde a la novèla d'un còp, per poder tornar dirèctament en arrèr se quicòm va mal.","also":["blue-green","blue green deployment","blue-green deployment","blau-verd"]},{"id":"zerodown","g":"change","word":"Desplegament sens interrupcion","text":"Metre una version novèla en linha sens que lo servici s'arrèste jamai pels utilizaires.","also":["zero downtime","zero-downtime","zero-downtime deployment","sens interrupcion"]},{"id":"chgenable","g":"change","word":"Acompanhament dels cambiaments","text":"Ajudar los cambiaments a capitar : pesar lo risc, obtenir la bona aprovacion e causir un bon moment. Se ditz tanben gestion dels cambiaments.","also":["gestion dels cambiaments","change enablement","change management"]},{"id":"cab","g":"change","word":"Comitat de consulta sus los cambiaments (CAB)","text":"Un grop que examina los cambiaments importants e decidís se e quora pòdon anar de l'avant.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Cambiament estandard","text":"Un cambiament de pauc de risc fach cada còp de la meteissa manièra, ja ben provada, doncas aprovat a l'avança.","also":["cambiaments estandards","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Cambiament normal","text":"Un cambiament que deu èsser verificat e aprovat abans d'anar de l'avant.","also":["cambiaments normals","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Cambiament d'urgéncia","text":"Un cambiament que se deu far tre ara per reparar o evitar un problèma grèu, amb una aprovacion mai rapida en consequéncia.","also":["cambiaments d'urgéncia","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizacion","text":"Far far a l'ordenador un trabalh repetit tot sol, per que siá mai rapid e fach de la meteissa manièra a cada còp.","also":["automatizat","automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructura","text":"Las maquinas, los rets e los servicis sus los quals fonciona lo logicial.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastructura coma còdi (IaC)","text":"Descriure tos servidors e tos paramètres dins de fichièrs gardats amb lo còdi, per que pòscan èsser tornats bastir exactament de la meteissa manièra a cada còp.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Nívol (cloud)","text":"Lojar d'ordenadors, d'espaci de gardament e de servicis a un gròs fornidor per internet, al lòc de possedir las maquinas tu-meteis.","also":["cloud","lo nívol","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Fornidor de nívol","text":"Una entrepresa que lòja de calcul per internet, coma Amazon Web Services (AWS), Microsoft Azure o Google Cloud.","also":["fornidors de nívol","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Albergament","text":"L'endrech ont ta aplicacion o ton site web viu e fonciona per que lo monde i pòsca accedir, sovent lojat a una entrepresa.","also":["hosting"]},{"id":"domain","g":"change","word":"Nom de domeni","text":"L'adreça web que lo monde tapa, coma example.com. La lòjas per an, doncas cal la renovelar.","also":["noms de domeni","domain","domain name","domain names"]},{"id":"dns","g":"change","word":"DNS","text":"Abreujament de « domain name system » : l'annuari d'internet, que transforma un nom coma example.com en l'adreça del bon ordenador.","also":["domain name system","sistèma de noms de domeni"]},{"id":"container","g":"change","word":"Contenidor","text":"Un paquet sarrat que conten una aplicacion e tot çò que li cal, per que foncione de la meteissa manièra sus qual ordenador que siá. Docker es l'esplech mai conegut.","also":["contenidors","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Maquina virtuala (VM)","text":"Un ordenador fals que fonciona dins un vertadièr, per que una sola gròssa maquina pòsca far coma mantuna.","also":["VM","VMs","virtual machine","virtual machines","maquinas virtualas"]},{"id":"serverless","g":"change","word":"Serverless (sens servidor)","text":"Far foncionar de còdi sens te cuidar de cap de servidor : lo fornidor lo fa foncionar quand cal e pagas çò que utilizas."},{"id":"lb","g":"change","word":"Repartidor de cargament (load balancer)","text":"Quicòm que reparteis los visitaires sus mantun servidor, per que cap d'èl siá pas subrecargat.","also":["load balancer","load balancers","repartidors de cargament"]},{"id":"cache","g":"change","word":"Memòria cache (cache)","text":"Una reserva practica de resultats recents gardats a la man, per que calga pas tornar cercar o calcular la meteissa causa. La vodar pòt reparar de paginas que semblan despassadas.","also":["cache","caches","caching","cached","memòria cache"]},{"id":"cdn","g":"change","word":"Ret de distribucion de contengut (CDN)","text":"Un ensemble mondial de servidors que gardan de còpias de tas paginas e imatges pròche dels visitaires, per que se cargan lèu.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migracion","text":"Desplaçar de donadas o de sistèmas d'un ancian montatge a un novèl, o cambiar amb precaucion la disposicion d'una basa de donadas.","also":["migracions","migration","migrations","database migration","migracion de basa de donadas"]},{"id":"service","g":"run","word":"Servici","text":"Quicòm qu'as bastit e de que las gents dependon, coma un site web o una aplicacion, que se'n pren suènh per que contunhe de foncionar. Marca « Aqueste projècte es un servici » e di çò que perpausa, qual l'utiliza e qual es de gàrdia.","also":["servicis"]},{"id":"uptimepct","g":"run","word":"Temps de disponibilitat (uptime)","text":"Quant de temps un servici fonciona, sovent en percentatge. 99,9 % daissa pasmens environ 43 minutas de pana per mes.","also":["uptime","percentatge d'uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Verificacion de disponibilitat","text":"Una verificacion automatica, cada qualques minutas, que ton servici respond encara. Se fracassa mantun còp de seguida, AI-gile dobrís una carta d'incident tot sol.","also":["uptime checks","verificacions de disponibilitat"]},{"id":"statuspage","g":"run","word":"Pagina d'estat","text":"Una pagina publica que mòstra se un servici fonciona (verd, irange o roge) amb la darrièra novèla, per que las gents que l'utilizan pòscan verificar allòc de demandar.","also":["paginas d'estat"]},{"id":"desk","g":"run","word":"Burèu de servici","text":"Ont arriban las questions e los senhalaments de las gents qu'utilizan ton servici. AI-gile classa cadun coma demanda, incident o idèa, e o ditz quand sembla quicòm de ja senhalat.","also":["burèus de servici","burèu d'ajuda","helpdesk"]},{"id":"svcrequest","g":"run","word":"Demanda de servici","text":"Qualqu'un que demanda quicòm d'ordinari, coma un compte novèl o un pauc d'ajuda, puslèu que de senhalar que quicòm es copat. Espèra son torn ; un incident passa abans.","also":["demandas de servici"]},{"id":"incident","g":"run","word":"Incident","text":"Quicòm que fonciona pas o fonciona mal pel monde que l'utiliza ara, coma lo site web copat o fòrça lent. Una carta 🔥 incident passa davant la fila : lo tornar far foncionar ven en primièr.","also":["incidents"]},{"id":"major","g":"run","word":"Incident major","text":"Un incident grand : fòrça gents tocadas, o d'argent o de donadas en dangièr. Un boton met totas las equipas dessús (eissam), revelha lo qu'es de gàrdia e demanda un punt d'estat cada 30 minutas.","also":["incidents majors"]},{"id":"oncall","g":"run","word":"De gàrdia","text":"Èsser lo que respond quand quicòm se copa, quitament la nuèch. Cada servici a un membre de l'equipa de gàrdia que se revelha en primièr per sos incidents.","also":["gàrdia","on-call"]},{"id":"replyby","g":"run","word":"Relambi de responsa","text":"Quant de temps una carta pòt esperar una primièra responsa, per exemple una ora per un incident. Aprèp, recep un relòtge roge, per que res siá pas oblidat d'escondon. Se ditz tanben objectiu de responsa.","also":["relambis de responsa","objectiu de responsa","objectius de responsa"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un cort agach en rèire aprèp un incident : çò que s'es passat, çò qu'a ajudat e çò que cal cambiar, sens acusar degun. Un incident se pòt pas barrar sens el.","also":["post-mortems","postmortem","revision aprèp incident"]},{"id":"problem","g":"run","word":"Problèma","text":"La causa amagada darrièr un o mantun incident. Una carta 🧩 problèma amassa los incidents que tornan totjorn, per que la causa siá trobada e corregida per de bon.","also":["problèmas"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa de fons","text":"La rason vertadièra que quicòm s'es copat, pas sonque çò qu'as vist anar de travèrs. Corregís la causa de fons e l'incident torna pas mai.","also":["causas de fons","causa primièra"]},{"id":"workaround","g":"run","word":"Biais","text":"Un mejan de far foncionar las causas fins que la vertadièra correccion siá prèsta, coma tornar aviar quicòm quand se bloca. Es escrich sus la carta de problèma per que degun aja pas de lo tornar trobar.","also":["biaisses","solucion provisòria"]},{"id":"knownerror","g":"run","word":"Error coneguda","text":"Un problèma que sa causa es compresa mas qu'es pas encara reparat, sovent amb un contornament escrich. 🧩 Errors conegudas las lista, per que tot lo monde utilize lo contornament al lòc de tornar cercar.","also":["errors conegudas"]},{"id":"runbook","g":"run","word":"Runbook","text":"D'instruccions pas a pas per corregir un tipe de trucs conegut, per que se faga de la meteissa manièra, lèu, cada còp. Aprèp un incident grand, l'equipa ne pòt prepausar un per que i dones ton OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Element de configuracion","text":"Una causa que ton servici ne depend, coma un servidor, un domeni, un certificat, una clau o un provesidor. 🗂️ Elements de configuracion los fa la lista per servici, per que vejas çò qu'un incident tòca e çò que cal renovelar o salvagardar.","also":["elements de configuracion"]},{"id":"expiry","g":"run","word":"Data d'expiracion","text":"La data aprèp la quala quicòm s'arrèsta de foncionar s'es pas renovelat, coma lo certificat de seguretat d'un site web o son adreça web. AI-gile susvelha aquestas datas e fa una carta per renovelar caduna 30 jorns abans, per que res s'arrèste pas per suspresa.","also":["datas d'expiracion","expiracion","susvelhança de las expiracions"]},{"id":"backup","g":"run","word":"Salvagarda","text":"Una còpia gardada de tas donadas d'abans, per i tornar se quicòm es perdut o damatjat. AI-gile fa una salvagarda de tos tablèus cada jorn.","also":["salvagardas","backup"]},{"id":"restore","g":"run","word":"Restabliment","text":"Tornar metre de donadas a partir d'una salvagarda. Una salvagarda compta vertadièrament pas que quand sabes que se pòt restablir, alara val la pena d'ensajar de temps en temps.","also":["restablir","restablit","restablida"]},{"id":"svcreview","g":"run","word":"Revision de servici","text":"Un còp d'uèlh en arrièr sus un mes d'un servici : incidents dobèrts e reparats, la rapiditat de las responsas, la disponibilitat e los tokens utilizats. La revision mensuala o mòstra per cada servici.","also":["revisions de servici","revision mensuala","revisions mensualas"]},{"id":"accessreview","g":"run","word":"Revision dels accès","text":"Verificar cada 90 jorns qual pòt totjorn intrar : ligams de partatge, ròtles dels amics e senhals e claus enregistrats. Gardas o levas cadun, per que los accèsses ancians demòron pas.","also":["revisions dels accès"]},{"id":"improvements","g":"run","word":"Lista dels melhoraments","text":"Tot çò que l'equipa decidiguèt de melhorar, en un sol luòc : suggestions de retro, accions de revision e correccions de problèmas, cadun amb son estat. Lo trobaràs dins 📈 Melhoraments.","also":["listas dels melhoraments","melhoraments"]},{"id":"tokencap","g":"run","word":"Limit de tokens","text":"Un limit mensual dels tokens que los agents d'un servici pòdon utilizar. A 80 % recebes un avertiment ; a 100 % lor trabalh de fons espèra lo mes que ven o que montes lo limit.","also":["limits de tokens"]},{"id":"svcmgmt","g":"run","word":"Gestion de servicis","text":"Tot çò que cal per que un servici demòre util e foncione per las personas que s'i fisan, jorn aprèp jorn.","also":["service management","gerir un servici"]},{"id":"itil","g":"run","word":"ITIL","text":"Una guida fòrça emplegada de bona gestion de servicis, que tracta d'incidents, de problèmas e de cambiaments. Lo nom voliá dire, a l'origina, IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestion de servicis informatics (ITSM)","text":"Menar la tecnologia coma un servici pel monde, amb de manièras claras de tractar las demandas, los incidents, los cambiaments e las melhoracions.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Servici gerit","text":"Un servici que qualqu'un mai fa foncionar e s'en ocupa per tu, jos un acòrdi sus la qualitat que deu aver.","also":["servicis gerits","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Responsable del servici","text":"La persona que respond d'un servici en entièr : cossí fonciona, çò que còsta e cossí melhora.","also":["responsables del servici","service owner","service owners"]},{"id":"sla","g":"run","word":"Acòrdi de nivèl de servici (SLA)","text":"Una promessa escricha als clients sus la qualitat de foncionament d'un servici, coma « en linha 99,9 % del temps » o « respondut en una ora », sovent amb un rembors s'es pas tengut.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Objectiu de nivèl de servici (SLO)","text":"L'objectiu pròpri de l'equipa sus la qualitat que deu aver un servici sus una periòde, sovent fixat un pauc mai estrich que la SLA, per mai de seguretat.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Indicador de nivèl de servici (SLI)","text":"La mesura vertadièra que verificas al respècte d'un objectiu, coma la part de visitas que se son plan cargadas.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Disponibilitat","text":"Se lo monde pòt utilizar un servici quand n'a besonh, sovent mesurat en uptime.","also":["nauta disponibilitat","availability","high availability"]},{"id":"downtime","g":"run","word":"Temps d'arrèst","text":"Lo temps ont un servici fonciona pas o es atudat, planificat o non.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Budget d'errors","text":"Lo pauc de fracàs que ton objectiu de fiabilitat permet. Tant qu'en demòra, pòdes prendre de risques amb los cambiaments ; un còp tot utilizat, alentisses.","also":["budgets d'errors","error budget","error budgets"]},{"id":"outage","g":"run","word":"Pana","text":"Un moment ont un servici es copat o grèument perturbat pels utilizaires.","also":["panas","outage","outages"]},{"id":"degraded","g":"run","word":"Servici degradat","text":"Fonciona, mas mal : lent, o amb d'unas parts que foncionan pas.","also":["degraded","degraded service","degradat"]},{"id":"monitoring","g":"run","word":"Susvelhança (monitoring)","text":"Agachar un servici automaticament tot lo temps, per que los problèmas sián reperats, idealament abans que los utilizaires o vejan.","also":["monitoring","susvelhança"]},{"id":"observability","g":"run","word":"Observabilitat","text":"Amb quina facilitat pòdes saber çò que se passa dins un sistèma dempuèi defòra, gràcias a sos jornals, sos nombres e sas traças.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Jornal (log)","text":"Un diari corrent qu'un programa ten de çò qu'es en trin de far, emplegat per comprene çò que s'es mal passat.","also":["log","logs","logging","jornals"],"noTip":1},{"id":"trace","g":"run","word":"Traça","text":"Un enregistrament de cossí una requèsta traversa las diferentas parts d'un sistèma, pas a pas, que mòstra ont s'es alentida.","also":["traças","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Laténcia","text":"Lo temps que quicòm pren per respondre, coma l'espèra entre lo clic e l'aparicion de la pagina.","also":["latency"]},{"id":"alert","g":"run","word":"Alèrta","text":"Un messatge automatic qu'indica que quicòm demanda d'atencion, coma lo site web que respond pas.","also":["alèrtas","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Fatiga d'alèrtas","text":"Quand i a tantas alèrtas que lo monde se met a las ignorar, e las importantas tanben.","also":["alert fatigue","alarm fatigue","fatiga d'alarmas"]},{"id":"dashboard","g":"run","word":"Tablèu de bòrd (dashboard)","text":"Un ecran que mòstra d'una agachada los nombres e los estats mai importants.","also":["dashboard","dashboards","tablèus de bòrd"],"noTip":1},{"id":"paging","g":"run","word":"Apèl d'urgéncia (paging)","text":"Apelar o desrevelhar d'urgéncia la persona de gardia per un problèma.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Escalada","text":"Far intervenir qualqu'un de mai competent o amb mai d'autoritat quand un problèma pòt pas èsser resolgut al nivèl actual, o pas pro lèu.","also":["escalate","escalated","escaladar"]},{"id":"triage","g":"run","word":"Triatge","text":"Triar rapidament los problèmas qu'arriban segon lor urgéncia e lor importància, per tractar lo pus grèu en primièr.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Impacte","text":"A quin ponch quicòm tòca lo monde : quantas personas, e quant grèument.","noTip":1},{"id":"urgency","g":"run","word":"Urgéncia","text":"Amb quina rapiditat quicòm deu èsser tractat. L'impacte e l'urgéncia amassa fixan la prioritat.","noTip":1},{"id":"plevels","g":"run","word":"Nivèls de prioritat (P1, P2…)","text":"Etiquetas per dire l'urgéncia d'un problèma. P1 es lo mai grèu e demanda una accion immediata.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Fila d'espèra de bilhets","text":"La lista de las demandas e dels incidents que son en espèra d'èsser tractats.","also":["files d'espèra de bilhets","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Primièra linha e segonda linha","text":"Nivèls d'assisténcia : la primièra linha pren l'apèl e repara las causas simplas ; la segonda a de competéncias mai prigondas pels cases mai dificils. Se ditz tanben tier 1 e tier 2.","also":["primièra linha","segonda linha","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Cap d'incident","text":"L'unica persona que mena la responsa a un incident, per que tot lo monde sàpia qual decidís e qual fa de qué.","also":["caps d'incident","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Temps de responsa","text":"Lo temps que passa abans que qualqu'un prenga un primièr còp una demanda o un incident.","also":["temps de responsa","response time","response times"]},{"id":"resolution","g":"run","word":"Temps de resolucion","text":"Lo temps que cal per tractar completament una demanda o un incident, del senhalament a la reparacion.","also":["temps de resolucion","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Temps mejan de recuperacion (MTTR)","text":"En mejana, lo temps que cal per refar foncionar un servici aprèp una pana. MTTR pòt voler dire de causas un pauc diferentas, doncas di çò que mesures.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Temps mejan entre panas (MTBF)","text":"En mejana, lo temps qu'un servici fonciona abans que quicòm se cope.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Basa de donadas de gestion de configuracion (CMDB)","text":"La lista de totes tos elements de configuracion e cossí son ligats, per veire çò que depend de qué.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Ben (asset)","text":"Tot çò de valor que possedisses o pagas per far foncionar lo servici, coma un portable, una licéncia de logicial o un domeni.","also":["bens","asset","assets","actiu"],"noTip":1},{"id":"capplan","g":"run","word":"Planificacion de la capacitat","text":"S'assegurar que i aurà pro de poténcia d'ordenador, d'espaci de gardament e de monde per çò que ven.","also":["plan de capacitat","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Cambiament d'escala (scaling)","text":"Far fàcia a mai d'utilizaires en balhant mai de poténcia a una maquina (scaling up) o en apondent mai de maquinas (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Continuitat d'activitat","text":"De plans per far tenir las causas importantas quand quicòm de grand va mal, coma perdre un burèu, un provesidor clau o los ordenadors.","also":["plan de continuitat d'activitat","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Represa aprèp sinistre (DR)","text":"Lo plan e los esplechs per tornar aver un servici aprèp un incident grèu, coma perdre tot un centre de donadas.","also":["DR","disaster recovery","plan de represa"]},{"id":"rto","g":"run","word":"Durada maximala d'interrupcion admissibla (RTO)","text":"Lo temps maximum qu'un servici pòt demorar copat aprèp un sinistre, abans de deure tornar foncionar.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Pèrda maximala de donadas admissibla (RPO)","text":"Quantas donadas recentas te pòdes permetre de perdre, mesurat en temps. Un RPO d'una ora vòl dire de salvaments almens cada ora.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redondància","text":"Aver de recambis prèsts, coma un segond servidor, per que una pana arrèste pas lo servici.","also":["redondant","redundancy"]},{"id":"failover","g":"run","word":"Basculament automatic (failover)","text":"Passar tot sol a un sistèma de recambi quand l'abitual se copa.","also":["failover","fail over","basculament"]},{"id":"spof","g":"run","word":"Punt unic de fallida","text":"Una pèça que fa tombar tot amb ela quand se copa, perque i a pas de recambi.","also":["punts unics de fallida","single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Fenèstra de mantenença","text":"Un moment planificat ont un servici pòt èsser en pausa o lent per sa mantenença, anonciat als utilizaires a l'avança.","also":["fenèstras de mantenença","maintenance window","maintenance windows","planned maintenance","mantenença planificada"]},{"id":"handover","g":"run","word":"Passacion de consignas","text":"Passar lo trabalh, los saberes e la responsabilitat a una autra persona o equipa, per que res se pèrda pas.","also":["passacions de consignas","handover","handovers"]},{"id":"kb","g":"run","word":"Basa de coneissença","text":"Una colleccion d'articles d'ajuda e de responsas, pels utilizaires e per l'equipa.","also":["bases de coneissença","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Satisfaccion dels clients (CSAT)","text":"Una nòta dels utilizaires que ditz a quin ponch èran contents, sovent demandada un còp una demanda tampada.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Provesidor","text":"Una entrepresa de defòra de la quala depenes, coma ton fornidor d'albergament. Se ditz tanben vendeire o tèrç.","also":["provesidors","supplier","suppliers","vendor","vendors","third party","tèrç"],"noTip":1},{"id":"retire","g":"run","word":"Fin de vida d'un servici","text":"Atudar un servici per de bon, en seguretat : avertir sos utilizaires, tractar sas donadas e sos accèsses, e arrestar sos còsts.","also":["tampar un servici","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Fin de vida (EOL)","text":"Quand un produch recep pas mai de mesas a jorn ni d'assisténcia de son fabricant, doncas deu èsser remplaçat.","also":["EOL","end of life","end-of-life","fin de vida"]},{"id":"cybersec","g":"sec","word":"Ciberseguretat","text":"Protegir los sistèmas e las donadas contra las intrusions, los panatoris e los degalhs.","also":["cybersecurity","cyber security","ciberseguretat","seguretat informatica"]},{"id":"authn","g":"sec","word":"Autentificacion","text":"Verificar qual es qualqu'un, sovent amb un senhal o un còdi. Sovent abreujat authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Autorizacion","text":"Verificar çò que qualqu'un a lo drech de far un còp que sabes qual es. Sovent abreujat authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Autentificacion a mantun factor (MFA)","text":"Se connectar amb doas pròvas o mai, coma un senhal mai un còdi sus ton telefòn. Se ditz tanben dos factors (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","autentificacion a dos factors"]},{"id":"sso","g":"sec","word":"Connexion unica (SSO)","text":"Se connectar un còp per intrar dins mantun sistèma, coma utilizar ton compte de trabalh pertot.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Gestionari de senhals","text":"Una aplicacion que crea de senhals fòrts e se'n remembra per tu.","also":["gestionaris de senhals","password manager","password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"Un senhal, una clau o un autre còdi privat qu'un programa utiliza per intrar dins quicòm. Deu jamai èsser partejat ni escrich dins lo còdi.","also":["secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"Clau d'API","text":"Un còdi secret que daissa un programa utilizar l'API d'un autre servici, e que mòstra qual l'utiliza (e qual paga).","also":["claus d'API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Geton d'accès","text":"Un laissa-passar temporari que pròva qu'un programa a lo drech d'intrar, per que aja pas besonh de ton senhal cada còp. Es pas la meteissa causa qu'un token d'IA.","also":["getons d'accès","access token","access tokens","token d'accès"]},{"id":"encryption","g":"sec","word":"Chifratge","text":"Embolhar d'informacions per que sol qualqu'un amb la bona clau las pòsca legir.","also":["chiframent","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"La manièra segura de far viatjar las paginas web, indicada pel cadenat dins ton navegador, per que degun entremitan las pòsca legir ni cambiar."},{"id":"cert","g":"sec","word":"Certificat SSL/TLS","text":"Una carta d'identitat numerica que daissa un site web provar qual es e utilizar HTTPS. Expira, doncas cal lo renovelar.","also":["certificat TLS","certificat SSL","certificat","certificats","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"Las règlas que dison qual pòt veire o cambiar de qué.","also":["permission","permissions","autorizacions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Privilègi minimal","text":"Balhar a cada persona o programa sonque l'accès que vertadièrament li cal, e sonque tant de temps qu'en a besonh.","also":["principi del privilègi minimal","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Contraròtle d'accès per ròtles (RBAC)","text":"Balhar l'accès per ròtle, coma legeire o editor, puslèu que persona per persona.","also":["RBAC","role-based access","accès per ròtles"]},{"id":"vuln","g":"sec","word":"Vulnerabilitat","text":"Una febleta que qualqu'un poiriá emplegar per intrar o far de mal.","also":["vulnerabilitats","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Una febleta que los atacants coneisson abans que los fabricants aguèsson agut cap de temps per la reparar.","also":["zero-days","zero day","jorn zèro"]},{"id":"malware","g":"sec","word":"Logicial malvolent (malware)","text":"De logicial nosible, coma los virus, fach per degalhar, espiar o panar.","also":["malware","logicial malvolent"]},{"id":"ransomware","g":"sec","word":"Ransomware (logicial de rançon)","text":"Un malware que clava tos fichièrs e demanda d'argent per los daissar tornar accessibles. De bonas salvagardas son la melhora defensa.","also":["ransomware","ransomware attack","logicial de rançon"]},{"id":"phishing","g":"sec","word":"Pesca de donadas (phishing)","text":"De messatges falses que ensajan de t'enganar per te far balhar de senhals o d'argent, o dobrir quicòm de nosible.","also":["phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Engenhariá sociala","text":"Enganar las personas, e pas los ordenadors, per obtenir un accès, coma un apèl fals de l'« assisténcia IT »."},{"id":"firewall","g":"sec","word":"Parafuòc (firewall)","text":"Un gardian que decidís quin tràfic de ret pòt intrar o sortir.","also":["firewall","firewalls","parafuòcs"]},{"id":"vpn","g":"sec","word":"VPN","text":"Abreujament de « virtual private network » : una ligason privada e embolhada sus internet, sovent emplegada per accedir en seguretat als sistèmas de trabalh.","also":["virtual private network","ret privada virtuala"]},{"id":"ddos","g":"sec","word":"Refús de servici (DoS, DDoS)","text":"Inondar un servici amb tant de tràfic fals que lo monde vertadièr pòt pas l'utilizar. DDoS vòl dire que ven de mantun ordenador a l'encòp.","also":["DoS","DDoS","denial of service","DDoS attack","refús de servici"]},{"id":"pentest","g":"sec","word":"Tèst d'intrusion (pen test)","text":"Engatjar d'especialistas amistoses per ensajar d'intrar, per que las febletats sián trobadas abans que d'atacants vertadièrs las trapen.","also":["pen test","pen testing","penetration test","penetration testing","pentest","tèst d'intrusion"]},{"id":"audit","g":"sec","word":"Audit de seguretat","text":"Una verificacion rigorosa de la proteccion de quicòm, al respècte d'una lista de bonas practicas.","also":["audits de seguretat","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelizacion de las menaças","text":"Pensar a qual poiriá atacar quicòm, cossí, e çò que fariás per l'arrestar.","also":["modèl de menaças","threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Fuga de donadas","text":"Quand d'informacions privadas arriban a de personas que las deurián pas aver, o se pèrdon o son cambiadas sens permission.","also":["fugas de donadas","data breach","data breaches","violacion de donadas"]},{"id":"pii","g":"sec","word":"Donadas personalas","text":"Tota informacion sus una persona que pòt èsser identificada, coma un nom, una adreça de corrièl o un lòc. Se ditz tanben PII.","also":["PII","personally identifiable information","donadas personalas"]},{"id":"gdpr","g":"sec","word":"RGPD","text":"La lei europèa sus las donadas personalas (lo Reialme Unit a sa pròpria version) : collècta sonque çò que te cal, garda-lo en seguretat, e daissa lo monde veire o suprimir las sieunas.","also":["GDPR","General Data Protection Regulation","Reglament general sus la proteccion de las donadas"]},{"id":"dataprot","g":"sec","word":"Proteccion de las donadas","text":"Se cuidar plan de las donadas personalas e dins lo quadre de la lei.","also":["lei de proteccion de las donadas","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Politica de confidencialitat","text":"Una pagina publica que ditz quinas donadas personalas collèctas, perqué, e çò que ne fas.","also":["declaracion de confidencialitat","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consentiment","text":"Un « òc » clar e liure d'una persona a l'utilizacion de sas donadas d'una manièra precisa. Lo pòt retirar a tot moment.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Un pichon fichièr qu'un site web enregistra dins ton navegador per se remembrar de causas, coma d'èsser connectat. D'unes demandan d'en primièr ton consentiment.","also":["cookies","cookie"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizacion de las donadas","text":"Collectar e gardar sonque las donadas personalas que te fan vertadièrament besonh pel trabalh.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Conservacion de las donadas","text":"Quant de temps las donadas son gardadas abans d'èsser suprimidas. Las gardar pas mai que cal es mai segur e sovent obligatòri per lei.","also":["durada de conservacion","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizacion","text":"Cambiar de donadas per que degun pòsca pas mai èsser identificat rasonablament a partir d'elas.","also":["anonimizat","anonymisation","anonymised","anonymization","anonymous data","donadas anonimas"]},{"id":"pseudo","g":"sec","word":"Pseudonimizacion","text":"Remplaçar de noms e d'autres detalhs per de còdis, amb una clau gardada a despart per los religar. Son totjorn de donadas personalas.","also":["pseudonimizat","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Contracte de tractament de donadas (DPA)","text":"Un contracte que ditz cossí un provesidor pòt tractar de donadas personalas per ton compte.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Analisi d'impacte sus la proteccion de las donadas (DPIA)","text":"Un agach atentiu, abans de començar, sus cossí un plan d'utilizacion de donadas personalas poiriá tocar lo monde e cossí redusir los risques.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Jornal d'audit","text":"Un enregistrament de qual a fach de qué e quora, per que las accions pòscan èsser verificadas aprèp.","also":["jornals d'audit","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Conformitat","text":"Seguir las leis, las règlas e las nòrmas que s'aplican a tu, e poder mostrar que o fas.","also":["conforme","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Una nòrma internacionala coneguda per gerir la seguretat de l'informacion. Las entrepresas pòdon èsser certificadas segon aquela nòrma.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un rapòrt american, verificat per d'auditors extèrnes, que mòstra qu'una entrepresa s'ocupa plan de las donadas dels clients.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Una IA que trabalha tota sola sus una tasca : legís lo còdi, fa de cambiaments, lança de verificacions e ne rend compte. Son trabalh es pasmens verificat.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Los pichons tròces de tèxte que legís e escriu una IA, d'environ tres quarts de mot cadun. L'usatge de l'IA se compta en tokens, doncas mens de tokens daissan mai de ton ofèrta.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Una pichona comanda que se lança tota sola a un moment fixat, per exemple quand una session IA comença, per que l'equipa ausisca tos comentaris.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intelligéncia artificiala (IA)","text":"De sistèmas informatics que fan de causas que pensam d'ordinari reservadas a las personas, coma escriure, respondre a de questions o reconéisser d'imatges.","also":["IA","AI","artificial intelligence","intelligéncia artificiala"],"noTip":1},{"id":"ml","g":"ai","word":"Aprendissatge automatic (ML)","text":"Una manièra de far que los ordenadors aprengan de modèls a partir de fòrça exemples, al lòc de lor balhar de règlas exactas.","also":["ML","machine learning","aprendissatge automatic"]},{"id":"model","g":"ai","word":"Modèl","text":"Lo « cervèl » format d'un sistèma IA, bastit en aprenent a partir d'un gròs nombre d'exemples. Los modèls difèron per competéncia, rapiditat e prètz.","also":["modèls","model","models","AI model","modèl d'IA"],"noTip":1},{"id":"llm","g":"ai","word":"Gròs modèl de lenga (LLM)","text":"Un modèl d'IA format sus de quantitats enòrmas de tèxte, per que sàpia legir e escriure una lenga.","also":["LLM","LLMs","large language model","gròs modèl de lenga"]},{"id":"genai","g":"ai","word":"IA generativa","text":"Una IA que crea de causas novèlas, coma de tèxtes, d'imatges o de còdi, al lòc de sonque las triar o las reconéisser.","also":["GenAI","generative AI","IA generativa"]},{"id":"chatbot","g":"ai","word":"Chatbot (agent conversacional)","text":"Un programa amb lo qual parlas amb de mots de cada jorn, en tapant o en parlant.","also":["chatbot","chatbots","agent conversacional"]},{"id":"prompt","g":"ai","word":"Prompt (consigna)","text":"Çò que balhas a una IA : ta question o tas instruccions, mai tot çò que li sometes. De consignas mai claras balhan sovent de melhoras responsas.","also":["prompts","prompt","consigna","consignas"]},{"id":"prompteng","g":"ai","word":"Engenhariá de prompts","text":"L'art d'escriure de prompts que balhan de resultats fisables e utils.","also":["prompt engineering","escriure de prompts"]},{"id":"sysprompt","g":"ai","word":"Prompt sistèma","text":"D'instruccions de fons qu'una IA recep abans que la conversacion comence, que fixan son ròtle e sas règlas. Pesan mai que çò que tapas.","also":["prompts sistèma","system prompt","system prompts","system instruction","system instructions","instruccion sistèma"]},{"id":"context","g":"ai","word":"Contèxt","text":"Tot çò que l'IA pòt veire pendent que trabalha : las instruccions, tos messatges, los fichièrs qu'a legits e las responsas d'abans.","noTip":1},{"id":"ctxwin","g":"ai","word":"Fenèstra de contèxt","text":"Quant una IA pòt tenir en memòria a l'encòp, mesurat en tokens. Al delà, las partidas mai ancianas son daissadas o resumidas.","also":["fenèstras de contèxt","context window","context windows"]},{"id":"session","g":"ai","word":"Session","text":"Una conversa de trabalh amb una IA, del començament a la fin. Una session novèla comença amb una memòria blanca.","also":["sessions","session"],"noTip":1},{"id":"memory","g":"ai","word":"Memòria","text":"De nòtas qu'una IA ten entre las sessions, per se remembrar de tas preferéncias e de las decisions passadas.","noTip":1},{"id":"hallucination","g":"ai","word":"Alucinacion","text":"Quand una IA ditz quicòm que sembla segur mas qu'es inventat o fals. Verifica los fachs importants.","also":["alucinacions","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Formacion del modèl (training)","text":"Ensenhar a un modèl en li mostrar un gròs nombre d'exemples, abans que degun l'utilize.","also":["formacion","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Donadas de formacion","text":"Los exemples dels quals un modèl a aprés. Sa coneissença s'arrèsta a la data de la collècta d'aquelas donadas.","also":["jòc de formacion","training data","training set"]},{"id":"cutoff","g":"ai","word":"Data d'arrèst de la coneissença","text":"La data ont la coneissença integrada d'una IA s'acaba. Sabrà pas res de çò que ven aprèp, levat se o va cercar.","also":["knowledge cutoff","training cutoff","data d'arrèst"]},{"id":"finetune","g":"ai","word":"Afinament (fine-tuning)","text":"Una formacion de mai d'un modèl existent amb tos pròpris exemples, per lo far melhor sus un trabalh particular.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","afinament"]},{"id":"inference","g":"ai","word":"Inferéncia","text":"Un modèl d'IA qu'es vertadièrament utilizat per respondre a quicòm, al contrari de quand es format.","also":["inference","model inference","inferéncia del modèl"]},{"id":"tooluse","g":"ai","word":"Utilizacion d'esplechs","text":"Una IA que pòt far de causas, pas sonque parlar : executar de comandas, legir de fichièrs o cercar sul web, gràcias als esplechs que l'aplicacion li dòna.","also":["tool use","tool calling","tool call","tool calls","apèl d'esplech"]},{"id":"subagent","g":"ai","word":"Sosagent","text":"Una IA ajudanta a la quala una IA principala confisa un trabalh mai pichon, e de la quala recep lo resultat.","also":["sosagents","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multiagent","text":"Mantunas IA que trabalhan amassa sus un meteis trabalh, caduna amb sa part, coma una pichona equipa.","also":["multi-agent","multi-agent system","sistèma multiagent"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Quant una IA pòt far tota sola abans de deure demandar a una persona.","also":["autonòm","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Uman dins la bocla","text":"Gardar una persona implicada per verificar o aprovar çò que fa l'IA als moments claus. Dins AI-gile, es tu.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Gardafòls","text":"De limitas e de verificacions que gardan en seguretat las accions d'una IA, coma d'aver besonh d'una aprovacion abans que quicòm passe en linha. Redusisson lo risc d'errors, mas las exclusisson pas.","also":["gardafòl","guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Generacion aumentada per recuperacion (RAG)","text":"Daissar una IA cercar dins tos pròpris documents abans de respondre, per que sas responsas se basen sus tos fachs.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (representacion vectoriala)","text":"Transformar un tèxte en una lista de nombres que captura son sens, per qu'un ordenador pòsca trobar de causas que significan quicòm de pròche.","also":["embeddings","embedding"]},{"id":"vectordb","g":"ai","word":"Basa de donadas vectoriala","text":"Una basa de donadas facha per cercar aquelas listas de nombres (embeddings), per trobar de contenguts de sens pròche.","also":["bases de donadas vectorialas","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Una manièra comuna de brancar d'esplechs e de fonts de donadas a d'aplicacions IA, per que una IA los pòsca utilizar.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Un paramètre que règla l'audàcia de las responsas d'una IA. Bassa, balha de responsas mai establas e previsiblas ; nauta, de responsas mai variadas. Cap de las doas la fa totjorn aver rason.","also":["temperature","model temperature","temperatura del modèl"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Capable de trabalhar amb mai d'un genre d'informacion, coma lo tèxte, los imatges e lo son.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Evaluacion (eval)","text":"Un tèst planificat de cossí una IA se'n sortís sus d'exemples causits, per poder comparar de modèls o de prompts.","also":["eval","evals","evaluation","evaluacions"]},{"id":"bias","g":"ai","word":"Bias (prejutjat)","text":"Quand una IA (o una persona) pencha injustament d'un costat, sovent a causa de çò que l'a formada.","also":["bias","biased","prejutjat"],"noTip":1},{"id":"responsible","g":"ai","word":"IA responsabla","text":"Utilizar l'IA de manièra justa, segura e onèsta, amb de personas que respondon totjorn dels resultats.","also":["IA etica","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Injeccion de prompt","text":"Una engana ont d'instruccions amagadas dins una pagina web o un fichièr ensajan de far far a una IA quicòm que son utilizaire a pas demandat.","also":["injeccions de prompt","prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limita de debit","text":"Un plafon sul nombre de requèstas que pòdes mandar a un servici dins un temps balhat. Se lo depassas, cal esperar.","also":["limitas de debit","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limita d'utilizacion","text":"Quant de trabalh IA ton forfait permet sus una periòde, aprèp la quala s'arrèsta o còsta mai.","also":["limitas d'utilizacion","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding (programar a l'ambiéncia)","text":"Bastir de logicials en descrivent sustot çò que vòls a una IA e en la daissant escriure lo còdi.","also":["vibe-coding","vibe coding"]},{"id":"budget","g":"money","word":"Budget","text":"La soma d'argent botada de costat per quicòm.","also":["budgets","budget"],"noTip":1},{"id":"costest","g":"money","word":"Estimacion de còst","text":"Una estimacion aproximativa del còst de quicòm, abans de començar.","also":["estimacions de còst","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Retorn sus investiment (ROI)","text":"Çò que te torna comparat amb çò qu'as botat. Se es positiu, valiá la pena.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Còst total de possession (TCO)","text":"Tot çò que quicòm còsta vertadièrament sus tota sa vida, pas sonque lo prètz de crompa : foncionament, assisténcia, mesas a nivèl e, al final, sa retirada.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx e OpEx","text":"Lo CapEx es l'argent despensat d'en primièr per de causas que gardas ; l'OpEx es la despensa contunha, coma las facturas de cada mes.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonament","text":"Pagar regularament, d'ordinari cada mes o cada an, per contunhar d'utilizar quicòm.","also":["abonaments","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Logicial coma servici (SaaS)","text":"Un logicial que utilizas en linha e pagas per abonament, mentre que lo fabricant lo fa foncionar per tu.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Pagar çò que consomas","text":"Pagar sonque çò que utilizas, coma lo nívol o los tokens d'IA.","also":["pay as you go","pay-as-you-go","usage-based pricing","paga a l'usatge"]},{"id":"overage","g":"money","word":"Depassament","text":"Un usatge al delà de çò que ton forfait compren, que pòt costar mai.","also":["depassaments","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alèrta de facturacion","text":"Un messatge quand la despensa o l'usatge atenh un nivèl qu'as causit. T'avertís, mas arrèsta pas totjorn los cobraments seguents.","also":["alèrtas de facturacion","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Nivèl gratuit","text":"Un nivèl gratuit d'un servici pagant, amb de limitas. Practic per començar.","also":["forfait gratuit","free tier","free plan"]},{"id":"pricing","g":"money","word":"Forfait tarifari","text":"Los diferents paquets qu'un servici vend, cadun amb son prètz e sas limitas.","also":["forfaits tarifaris","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licéncia","text":"Las règlas que dison cossí pòdes utilizar, copiar, cambiar o partejar quicòm qu'una autra persona a fach, coma de logicials, de poliças o d'imatges.","also":["licéncias","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (còdi dubèrt)","text":"Un logicial que son còdi pòt èsser legit, utilizat e sovent cambiat per tot lo monde, gratuitament, jos las règlas de sa licéncia.","also":["open-source","open source","open source software","OSS","còdi dubèrt"]},{"id":"osslicence","g":"money","word":"Licéncia open source","text":"Las règlas que vènon amb de còdi open source. D'unas te daissan far gaireben tot (coma MIT) ; d'autras te demandan de partejar tanben tos cambiaments (coma GPL).","also":["licéncias open source","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietari","text":"Qu'es la proprietat d'una entrepresa e que se pòt pas copiar ni cambiar liurament. L'opausat de l'open source.","also":["logicial proprietari","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Drech d'autor (copyright)","text":"Lo drech legal d'un creator de contrarotlar las còpias de son òbra, çò que compren lo còdi e los tèxtes.","also":["copyright","copyrighted","drech d'autor"],"noTip":1},{"id":"ip","g":"money","word":"Proprietat intellectuala (PI)","text":"D'idèas e de creacions que la lei considèra coma una proprietat, coma lo còdi, los dessenhs, los noms e los logotipes.","also":["PI","IP","intellectual property","proprietat intellectuala"]},{"id":"tos","g":"money","word":"Condicions d'utilizacion","text":"Las règlas qu'acceptas quand utilizas un servici.","also":["condicions generalas","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contracte","text":"Un acòrdi escrich entre dos costats que la lei fa respectar.","also":["contractes","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Descripcion del trabalh (SOW)","text":"Un document que fixa exactament quin trabalh se farà, per quora e per quant.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Prètz fixe","text":"Un prètz convengut per tot lo trabalh, quin que siá lo temps que pren.","also":["fixed price","fixed-price","prètz forfait"]},{"id":"tm","g":"money","word":"Temps passat e fornituras","text":"Pagar las oras vertadièrament trabalhadas e las causas vertadièrament emplegadas, al lòc d'un prètz fixe.","also":["T&M","time and materials","regia"]},{"id":"invoice","g":"money","word":"Factura","text":"Una nòta que demanda lo paiament d'un trabalh fach o de marcandisas fornidas.","also":["facturas","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Dependéncia d'un fornidor (vendor lock-in)","text":"Quand quitar un fornidor es tan dificil o car que i demòras enganchat.","also":["lock-in","vendor lock-in","enfermament"]},{"id":"procurement","g":"money","word":"Crompas (procurement)","text":"Lo processus de causir e crompar a de fornidors.","also":["procurement","aprovisionament"]},{"id":"servicecredit","g":"money","word":"Crèdit de servici","text":"Argent tornat o rebais que recebes quand un fornidor respècta pas son SLA.","also":["crèdits de servici","service credit","service credits"]}]}};
